{{$safeEditorId = preg_replace( "/[^a-zA-Z0-9\-_]/", '_', $editorId );}}
<div class="cMyMedia" data-controller='core.global.editor.mymedia, core.global.editor.insertable' data-editorid='{$editorId}'>
	<div id="elEditor{$safeEditorId}Attach">
