						{{if $item->canOnMessage( 'delete' )}}
							<li>
								<a href='{$item->url()->csrf()->setQueryString( array( 'do' => 'messageDelete', 'meta_id' => $id ) )}' data-confirm>{lang="delete"}</a>
							</li>
						{{endif}}
					</ul>
				{{endif}}
