<div id='elGuestTerms' class='ipsPad_half ipsJS_hide' data-role='{{if \IPS\Request::i()->cookieConsentEnabled()}}cookieConsentBar{{else}}guestTermsBar{{endif}}' data-controller='core.front.core.guestTerms'>
