<meta name="application-name" content="{{if isset( $manifest['name'] )}}{$manifest['name']}{{else}}{setting="board_name"}{{endif}}">
<meta name="apple-mobile-web-app-title" content="{{if isset( $manifest['name'] )}}{$manifest['name']}{{else}}{setting="board_name"}{{endif}}">
{{if isset( $manifest['theme_color'] )}}
	<meta name="theme-color" content="{$manifest['theme_color']}">
{{else}}
	<meta name="theme-color" content="{theme="header"}">
{{endif}}
{{if isset( $manifest['background_color'] )}}
	<meta name="msapplication-TileColor" content="{$manifest['background_color']}">
{{endif}}
{{if \IPS\Settings::i()->icons_mask_icon AND \IPS\Settings::i()->icons_mask_color}}
	<link rel="mask-icon" href="{file="\IPS\Settings::i()->icons_mask_icon" extension="core_Icons" cb="$manifest['cache_key']"}" color="{setting="icons_mask_color"}">
{{endif}}

{{$homeScreen = json_decode( \IPS\Settings::i()->icons_homescreen, TRUE ) ?? array();}}
{{foreach $homeScreen as $name => $image}}
	{{if $name != 'original'}}
		{{if mb_strpos( $name, 'apple-touch-icon' ) !== FALSE}}
			{{if $name === 'apple-touch-icon-57x57'}}
				<link rel="apple-touch-icon" href="{file="$image['url']" extension="core_Icons" cb="$manifest['cache_key']"}">
			{{else}}
				<link rel="apple-touch-icon" sizes="{$image['width']}x{$image['height']}" href="{file="$image['url']" extension="core_Icons" cb="$manifest['cache_key']"}">
			{{endif}}
		{{elseif mb_strpos( $name, 'msapplication' ) !== FALSE}}
			<meta name="{$name}" content="{file="$image['url']" extension="core_Icons" cb="$manifest['cache_key']"}"/>
		{{else}}
			<link rel="icon" sizes="{$image['width']}x{$image['height']}" href="{file="$image['url']" extension="core_Icons" cb="$manifest['cache_key']"}">
		{{endif}}
	{{endif}}
{{endforeach}}

{{$apple = json_decode( \IPS\Settings::i()->icons_apple_startup, TRUE ) ?? array();}}
{{if \count( $apple )}}
	<meta name="mobile-web-app-capable" content="yes">
	<meta name="apple-touch-fullscreen" content="yes">
	<meta name="apple-mobile-web-app-capable" content="yes">

	{{foreach $apple as $name => $image}}
		{{if $name !== 'original'}}
			<link rel="apple-touch-startup-image" media="screen and (device-width: {expression="$image['width'] / $image['density']"}px) and (device-height: {expression="$image['height'] / $image['density']"}px) and (-webkit-device-pixel-ratio: {$image['density']}) and (orientation: {$image['orientation']})" href="{file="$image['url']" extension="core_Icons" cb="$manifest['cache_key']"}">
		{{endif}}
	{{endforeach}}
{{endif}}

<link rel="preload" href="{url="applications/core/interface/font/fontawesome-webfont.woff2?v=4.7.0" base="none" noprotocol="true"}" as="font" crossorigin="anonymous">

{{if isset( \IPS\Theme::i()->logo['front']['url'] ) AND \IPS\Theme::i()->logo['front']['url'] !== null }}
{{$logo = \IPS\File::get( 'core_Theme', \IPS\Theme::i()->logo['front']['url'] )->url;}}
<a href='{setting="base_url"}' id='elLogo' accesskey='1'><img src="{$logo}" alt='{setting="board_name" escape="true"}'></a>
{{else}}
<a href='{setting="base_url"}' id='elSiteTitle' accesskey='1'>{setting="board_name"}</a>
{{endif}}

{{if $pad}}<div class="ipsPad_half">{{endif}}
{{if $debug !== NULL}}
	<div class="ipsMessage ipsMessage_{$type}">
		{{if $parse}}
			{lang="$message"}
		{{else}}
			{$message|raw}
		{{endif}}
		<br><br>
		<pre>{$debug}</pre>
	</div>
{{else}}
	<p class="ipsMessage ipsMessage_{$type}">
		{{if $parse}}
			{lang="$message"}
		{{else}}
			{$message|raw}
		{{endif}}
	</p>
{{endif}}
{{if $pad}}</div>{{endif}}

{{if $debug !== NULL}}
	<div class="ipsMessage ipsMessage_{$type}">
		{{if $parse}}
			{lang="$message"}
		{{else}}
			{$message|raw}
		{{endif}}
		<br><br>
		<pre>{$debug}</pre>
	</div>
{{else}}
	<p class="ipsMessage ipsMessage_{$type}">
		{{if $parse}}
			{lang="$message"}
		{{else}}
			{$message|raw}
		{{endif}}
	</p>
{{endif}}

{{if $pages > 1}}
	<span class='ipsPagination ipsPagination_mini' id='elPagination_{expression="md5($baseUrl)"}'>
		{{foreach range( 1, ( 4 > $pages ) ? $pages : 4 ) as $i}}
			<span class='ipsPagination_page'><a href='{$baseUrl->setPage( $pageParam, $i )}' data-ipsTooltip title='{lang="go_to_page_x" sprintf="$i"}'>{$i}</a></span>
		{{endforeach}}
		{{if $pages > 4}}
			<span class='ipsPagination_last'><a href='{$baseUrl->setPage( $pageParam, $pages )}' data-ipsTooltip title='{lang="last_page"}'>{$pages} <i class='fa fa-caret-right'></i></a></span>
		{{endif}}
	</span>
{{endif}}

{{foreach $items as $child}}
	{{if $child->canView()}}
		{{if $children = $child->children()}}
			{{$id = md5( mt_rand() );}}
			<li class='ipsDrawer_itemParent'>
				<h4 class='ipsDrawer_title'><a href='#'>{$child->title()}</a></h4>
				<ul class='ipsDrawer_list'>
					<li data-action="back"><a href='#'>{lang="mobile_menu_back"}</a></li>
					{{if $child->link() && $child->link() !== '#'}}
						<li>
							<a href='{$child->link()}'>
								{$child->title()}
							</a>
						</li>
					{{endif}}
					{template="mobileNavigationChildren" group="global" app="core" params="$children"}
				</ul>
			</li>
		{{elseif $child instanceof \IPS\core\extensions\core\FrontNavigation\MenuHeader}}
			<li class='ipsDrawer_section'>
				{$child->title()}
			</li>
		{{elseif $child instanceof \IPS\core\extensions\core\FrontNavigation\MenuSeparator}}

		{{elseif $child instanceof \IPS\core\extensions\core\FrontNavigation\MenuButton}}
			<li class='ipsPad_half'>
				<a href='{$child->link()}' class='ipsButton ipsButton_important ipsButton_verySmall ipsButton_fullWidth'>
					{$child->title()}
				</a>
			</li>
		{{else}}
			<li>
				<a href='{$child->link()}' {{if method_exists( $child, 'target' ) AND $child->target()}}target='{$child->target()}'{{if $child->target() == '_blank'}} rel="noopener"{{endif}}{{endif}}>
					{$child->title()}
				</a>
			</li>
		{{endif}}
	{{endif}}
{{endforeach}}

{{foreach $items as $item}}
	{{if $preview or $item->canView()}}
		{{if $children = $item->children()}}
			{{$id = md5( mt_rand() );}}
			<li id='elNavigation_{$id}' class='ipsMenu_item ipsMenu_subItems'>
				<a href='{{if $item->link()}}{$item->link()}{{else}}#{{endif}}'>
					{$item->title()}
				</a>
				<ul id='elNavigation_{$id}_menu' class='ipsMenu ipsMenu_auto ipsHide'>
					{template="navBarChildren" app="core" group="global" params="$children, $preview"}
				</ul>
			</li>
		{{elseif $item instanceof \IPS\core\extensions\core\FrontNavigation\MenuHeader}}
			<li class='ipsMenu_title'>
				{$item->title()}
			</li>
		{{elseif $item instanceof \IPS\core\extensions\core\FrontNavigation\MenuSeparator}}
			<li class='ipsMenu_sep'>
				<hr>
			</li>
		{{elseif $item instanceof \IPS\core\extensions\core\FrontNavigation\MenuButton}}
			<li class='ipsPad_half'>
				<a href='{$item->link()}' class='ipsButton ipsButton_primary ipsButton_verySmall ipsButton_fullWidth'>
					{$item->title()}
				</a>
			</li>
		{{else}}
			<li class='ipsMenu_item' {$item->attributes()|raw}>
				<a href='{$item->link()}' {{if method_exists( $item, 'target' ) AND $item->target()}}target='{$item->target()}'{{if $item->target() == '_blank'}} rel="noopener"{{endif}}{{endif}}>
					{$item->title()}
				</a>
			</li>
		{{endif}}
	{{endif}}
{{endforeach}}

{{$first = TRUE;}}
{{foreach $roots as $id => $item}}
	{{if $preview or $item->canView()}}
		{{$active = $preview ? $first : $item->activeOrChildActive();}}
		{{if $active}}
			{{\IPS\core\FrontNavigation::i()->activePrimaryNavBar = $item->id;}}
		{{endif}}
		<li {{if $active}}class='ipsNavBar_active' data-active{{endif}} id='elNavSecondary_{$item->id}' data-role="navBarItem" data-navApp="{expression="mb_substr( \get_class( $item ), 4, mb_strpos( \get_class( $item ), '\\', 4 ) - 4 )"}" data-navExt="{expression="mb_substr( \get_class( $item ), mb_strrpos( \get_class( $item ), '\\' ) + 1 )"}">
			{{$children = $item->children();}}
			{{if $children}}
				<a href="{{if $item->link()}}{$item->link()}{{else}}#{{endif}}" id="elNavigation_{$id}" data-ipsMenu data-ipsMenu-appendTo='#{{if $parent}}elNavSecondary_{$parent}{{else}}elNavSecondary_{$id}{{endif}}' data-ipsMenu-activeClass='ipsNavActive_menu' data-navItem-id="{$item->id}" {{if $active}}data-navDefault{{endif}}>
					{$item->title()} <i class="fa fa-caret-down"></i><span class='ipsNavBar_active__identifier'></span>
				</a>
				<ul id="elNavigation_{$id}_menu" class="ipsMenu ipsMenu_auto ipsHide">
					{template="navBarChildren" app="core" group="global" location="front" params="$children, $preview"}
				</ul>
			{{else}}
				<a href="{{if $item->link()}}{$item->link()}{{else}}#{{endif}}" {{if method_exists( $item, 'target' ) AND $item->target()}}target='{$item->target()}'{{if $item->target() == '_blank'}} rel="noopener"{{endif}}{{endif}} data-navItem-id="{$item->id}" {{if $active}}data-navDefault{{endif}}>
					{$item->title()}<span class='ipsNavBar_active__identifier'></span>
				</a>
			{{endif}}
			{{if $subBars && isset( $subBars[ $id ] ) && \count( $subBars[ $id ] )}}
				<ul class='ipsNavBar_secondary {{if !$active}}ipsHide{{endif}}' data-role='secondaryNavBar'>
					{template="navBarItems" app="core" group="global" location="front" params="$subBars[ $id ], NULL, $item->id, $preview"}
					<li class='ipsHide' id='elNavigationMore_{$id}' data-role='navMore'>
						<a href='#' data-ipsMenu data-ipsMenu-appendTo='#elNavigationMore_{$id}' id='elNavigationMore_{$id}_dropdown'>{lang="more"} <i class='fa fa-caret-down'></i></a>
						<ul class='ipsHide ipsMenu ipsMenu_auto' id='elNavigationMore_{$id}_dropdown_menu' data-role='moreDropdown'></ul>
					</li>
				</ul>
			{{endif}}
		</li>
	{{endif}}
	{{$first = FALSE;}}
{{endforeach}}

{{if !empty( $buttons )}}
	{{usort( $buttons, function ($a, $b ){ if( isset( $a['primary'] ) && $a['primary'] ){ return 1; }else{ return 0;} } );}}
	{{$hasSecondary = false;}}
	<ul class="ipsList ipsList_inline" data-controller='core.admin.core.pageActions'>
		{{foreach $buttons as $action}}
			<li {{if isset( $action['primary'] ) && $action['primary']}}class='acpToolbar_primary'{{endif}}>
				{{if !( isset( $action['primary'] ) && $action['primary'] )}}
					{{$hasSecondary = true;}}
				{{endif}}
				<a
					{{if isset( $action['link'] )}}
						href='{{if mb_substr( $action['link'], 0, 1 ) === '#' or preg_match( '/^[a-z]{3,5}:\/\/.*$/', $action['link'] )}}{$action['link']}{{else}}{url="{$action['link']}"}{{endif}}'
					{{else}}
						href='#'
					{{endif}}
					{{if isset( $action['id'] )}}
						id='{$action['id']}'
					{{endif}}
					{{if isset( $action['menu'] )}}
						data-ipsMenu
						{{if !isset( $action['id'] )}}
							id='{{$id = md5( mt_rand() );}}{$id}'
						{{endif}}
					{{endif}}
					class='ipsButton {{if isset( $action['primary'] ) && $action['primary']}}ipsButton_primary{{elseif isset( $action['color'] )}}{$action['color']}{{else}}ipsButton_normal{{endif}} {{if isset( $action['class'] )}}{$action['class']}{{endif}}'
					{{if isset( $action['target'] )}}target="{$action['target']}"{{if $action['target'] == '_blank'}} rel="noopener"{{endif}}{{endif}}
					{{if isset( $action['tooltip'] )}}title="{$action['tooltip']}" data-ipsTooltip{{endif}}
					{{if isset( $action['data'] )}}
						{{foreach $action['data'] as $k => $v}}
							data-{$k}="{$v}"
						{{endforeach}}
					{{endif}}
				>
					<i class='fa fa-{$action['icon']}'></i> &nbsp;&nbsp;<span data-role="title">{lang="$action['title']"}</span>{{if isset( $action['menu'] ) || isset( $action['dropdown'] )}} <i class="fa fa-caret-down"></i>{{endif}}
				</a>
				{{if isset( $action['menu'] )}}
					<div id='{$id}_menu' class='ipsMenu {{if isset( $action['menuClass'] )}}{$action['menuClass']}{{endif}} ipsHide'>
						<ul>
							{{foreach $action['menu'] as $item}}
								{{if isset( $item['hr'] ) and $item['hr']}}
									<li class='ipsMenu_sep'><hr></li>
								{{else}}
									<li class="ipsMenu_item {{if isset( $item['class'] )}}{$item['class']}{{endif}}">
										<a href="{$item['link']}" {{if isset( $item['target'] )}}target='{$item['target']}'{{if $item['target'] == '_blank'}} rel="noopener"{{endif}}{{endif}} {{if isset( $item['data'] )}}{{foreach $item['data'] as $k => $v}} data-{$k}="{$v}"{{endforeach}}{{endif}}>
											{{if isset( $item['icon'] )}}
												<i class='fa fa-{$item['icon']}'></i> &nbsp;&nbsp;
											{{endif}}
											<span data-role="title">{lang="$item['title']"}</span>
										</a>
									</li>
								{{endif}}
							{{endforeach}}
						</ul>
					</div>
				{{endif}}
			</li>
		{{endforeach}}
		{{if $hasSecondary}}
			<li class='acpToolbar_more ipsResponsive_hideDesktop'>
				<a href='#' class='ipsButton ipsButton_light ipsButton_verySmall' data-action='expandPageActions'>
					<span data-role='more'>{lang="more_page_options"} <i class='fa fa-angle-down'></i></span>
					<span data-role='fewer' class='ipsHide'>{lang="fewer_page_options"} <i class='fa fa-angle-up'></i></span>
				</a>
			</li>
		{{endif}}
	</ul>
{{endif}}

{{$firstPage = $baseUrl->setPage( $pageParam );}}
{{if $activePage > 1 || $pages > 1}}
	{{$uniqId = mt_rand();}}
	<ul class='ipsPagination' id='elPagination_{expression="md5($baseUrl)"}_{$uniqId}' data-ipsPagination-seoPagination='{{if $firstPage->seoPagination}}true{{else}}false{{endif}}' data-pages='{$pages}' {{if $ajax and ( theme.ajax_pagination or \IPS\Request::i()->isAjax())}}data-ipsPagination {{if $pageParam != 'page'}}data-ipsPagination-pageParam='{$pageParam}'{{endif}} data-ipsPagination-pages="{$pages}" data-ipsPagination-perPage='{$perPage}'{{endif}}>
		{{if $simple}}
			{{if $activePage > 1}}
				<li class='ipsPagination_prev'><a href='{$baseUrl->setPage( $pageParam, $activePage - 1 )}' rel="prev" data-page='{expression="$activePage - 1"}' data-ipsTooltip title='{lang="prev_page"}'>{lang="prev"}</a></li>
			{{endif}}
			{{if $activePage < $pages}}
				<li class='ipsPagination_next'><a href='{$baseUrl->setPage( $pageParam, $activePage + 1 )}' rel="next" data-page='{expression="$activePage + 1"}' data-ipsTooltip title='{lang="next_page"}'>{lang="next"}</a></li>
			{{endif}}
		{{else}}
			{{if $activePage != 1}}
				<li class='ipsPagination_first'><a href='{$firstPage}' rel="first" data-page='1' data-ipsTooltip title='{lang="first_page"}'><i class='fa fa-angle-double-left'></i></a></li>
				<li class='ipsPagination_prev'><a href='{$baseUrl->setPage( $pageParam, $activePage - 1 )}' rel="prev" data-page='{expression="$activePage - 1"}' data-ipsTooltip title='{lang="prev_page"}'>{lang="prev"}</a></li>
				{{foreach range( ( ( $activePage - 5 ) > 0 ) ? ( $activePage - 5 ) : 1, $activePage - 1 ) as $idx => $i}}
					<li class='ipsPagination_page'><a href='{$baseUrl->setPage( $pageParam, $i )}' data-page='{$i}'>{$i}</a></li>
				{{endforeach}}
			{{else}}
				<li class='ipsPagination_first ipsPagination_inactive'><a href='{$firstPage}' rel="first" data-page='1' data-ipsTooltip title='{lang="first_page"}'><i class='fa fa-angle-double-left'></i></a></li>
				<li class='ipsPagination_prev ipsPagination_inactive'><a href='{$baseUrl->setPage( $pageParam, $activePage - 1 )}' rel="prev" data-page='{expression="$activePage - 1"}' data-ipsTooltip title='{lang="prev_page"}'>{lang="prev"}</a></li>
			{{endif}}
			<li class='ipsPagination_page ipsPagination_active'><a href='{$baseUrl->setPage( $pageParam, $activePage )}' data-page='{$activePage}'>{$activePage}</a></li>
			{{if $activePage != $pages}}
				{{foreach range( $activePage + 1, ( ( $activePage + 5 ) > $pages ) ? $pages : ( $activePage + 5 ) ) as $idx => $i}}
					<li class='ipsPagination_page'><a href='{$baseUrl->setPage( $pageParam, $i )}' data-page='{$i}'>{$i}</a></li>
				{{endforeach}}
				<li class='ipsPagination_next'><a href='{$baseUrl->setPage( $pageParam, $activePage + 1 )}' rel="next" data-page='{expression="$activePage + 1"}' data-ipsTooltip title='{lang="next_page"}'>{lang="next"}</a></li>
				<li class='ipsPagination_last'><a href='{$baseUrl->setPage( $pageParam, $pages )}' rel="last" data-page='{$pages}' data-ipsTooltip title='{lang="last_page"}'><i class='fa fa-angle-double-right'></i></a></li>
			{{else}}
				<li class='ipsPagination_next ipsPagination_inactive'><a href='{$baseUrl->setPage( $pageParam, ( $activePage + 1 > $pages ) ? $pages : $activePage + 1 )}' rel="next" data-page='{expression="( $activePage + 1 > $pages ) ? $pages : $activePage + 1"}' data-ipsTooltip title='{lang="next_page"}'>{lang="next"}</a></li>
				<li class='ipsPagination_last ipsPagination_inactive'><a href='{$baseUrl->setPage( $pageParam, $pages )}' rel="last" data-page='{$pages}' data-ipsTooltip title='{lang="last_page"}'><i class='fa fa-angle-double-right'></i></a></li>
			{{endif}}
			{{if $pages > 1}}
				<li class='ipsPagination_pageJump'>
					<a href='#' data-ipsMenu data-ipsMenu-closeOnClick='false' data-ipsMenu-appendTo='#elPagination_{expression="md5($baseUrl)"}_{$uniqId}' id='elPagination_{expression="md5($baseUrl)"}_{$uniqId}_jump'>{lang="pagination" sprintf="$activePage, $pages"} &nbsp;<i class='fa fa-caret-down'></i></a>
					<div class='ipsMenu ipsMenu_narrow ipsPadding ipsHide' id='elPagination_{expression="md5($baseUrl)"}_{$uniqId}_jump_menu'>
						<form accept-charset='utf-8' method='post' action='{$baseUrl->setPage( 'page', NULL )}' data-role="pageJump" data-baseUrl='#'>
							<ul class='ipsForm ipsForm_horizontal'>
								<li class='ipsFieldRow'>
									<input type='number' min='1' max='{$pages}' placeholder='{lang="page_number"}' class='ipsField_fullWidth' name='{$pageParam}'>
								</li>
								<li class='ipsFieldRow ipsFieldRow_fullWidth'>
									<input type='submit' class='ipsButton_fullWidth ipsButton ipsButton_verySmall ipsButton_primary' value='{lang="go"}'>
								</li>
							</ul>
						</form>
					</div>
				</li>
			{{endif}}
		{{endif}}
	</ul>
{{endif}}

{{if \IPS\Settings::i()->fb_pixel_id and \IPS\Settings::i()->fb_pixel_enabled}}
{{if $addScriptTags}}<script>{{endif}}
setTimeout( function() {
	{{foreach $events as $name => $params}}
		{{$inlineParams = '';}}
		{{if \count( $params )}}
			{{$inlineParams = json_encode( $params );}}
		{{endif}}
		{{if $inlineParams}}
		fbq('track', '{$name}', {$inlineParams|raw});
		{{else}}
		fbq('track', '{$name}');
		{{endif}}
	{{endforeach}}
}, {expression="\intval( \IPS\Settings::i()->fb_pixel_delay * 1000 )"} );
{{if $addScriptTags}}</script>{{endif}}
{{endif}}

{{if !isset( \IPS\Request::i()->fetchPoll )}}
<section data-controller='core.front.core.poll'>
{{endif}}
	{{if $poll->canVote() and request._poll != 'results' and ( !$poll->getVote() or request._poll == 'form') and $pollForm = $poll->buildForm()}}
		<h2 class='ipsType_sectionTitle ipsType_reset'>
			<span class='ipsType_break ipsContained'>
				{$poll->poll_question}&nbsp;&nbsp;
				{{if $poll->votes}}<p class='ipsType_reset ipsPos_right ipsResponsive_hidePhone ipsType_light ipsType_unbold ipsType_medium'><i class='fa fa-check-square-o'></i> {lang="poll_num_votes" pluralize="$poll->votes"}</p>{{endif}}
			</span>
		</h2>
		<div class='ipsPadding ipsClearfix' data-role='pollContents'>
			{$pollForm->customTemplate( array( \IPS\Theme::i()->getTemplate( 'global', 'core', 'global' ), 'pollForm' ), $url, $poll )|raw}
		</div>
	{{elseif ( $poll->canViewResults() and !$poll->canVote() ) or $poll->getVote() or ( request._poll == 'results' and $poll->canViewResults() )}}
		<h2 class='ipsType_sectionTitle ipsType_reset'>
			<span class='ipsType_break ipsContained'>
				{$poll->poll_question}&nbsp;&nbsp;
				{{if $poll->votes}}<p class='ipsType_reset ipsPos_right ipsResponsive_hidePhone ipsType_light ipsType_unbold ipsType_medium'><i class='fa fa-check-square-o'></i> {lang="poll_num_votes" pluralize="$poll->votes"}</p>{{endif}}
			</span>
		</h2>
		<div class='ipsPadding ipsClearfix' data-role='pollContents'>
			<ol class='ipsList_reset cPollList'>
				{{$i = 0;}}
				{{foreach $poll->choices as $questionId => $question}}
					{{$i++;}}
					<li>
						<h3 class='ipsType_sectionHead'><span class='ipsType_break ipsContained'>{$i}. {$question['question']}</span></h3>
						<ul class='ipsList_reset cPollList_choices'>
							{{foreach $question['choice'] as $k => $choice}}
								<li class='ipsGrid ipsGrid_collapsePhone'>
									<div class='ipsGrid_span4 ipsType_richText ipsType_break'>
										{$choice|raw}
									</div>
									<div class='ipsGrid_span7'>
										<span class='cPollVoteBar'>
											<span style='width: {{if array_sum( $question['votes'] ) > 0 }}{expression="\intval( ( $question['votes'][ $k ] / array_sum( $question['votes'] ) ) * 100 )"}{{else}}0{{endif}}%' data-votes='{{if array_sum( $question['votes'] ) > 0}}{expression="round( ( $question['votes'][ $k ] / array_sum( $question['votes'] ) ) * 100, 2 )"}{{else}}0{{endif}}%' {{if array_sum( $question['votes'] ) && \intval( ( $question['votes'][ $k ] / array_sum( $question['votes'] ) ) * 100 ) > 30}}class='cPollVoteBar_inside'{{endif}}></span>
										</span>
									</div>
									<div class='ipsGrid_span1 ipsType_small'>
										{{if $poll->canSeeVoters() && $question['votes'][ $k ] > 0}}
											<a href='{url="app=core&module=system&controller=poll&do=voters&id={$poll->pid}&question={$questionId}&option={$k}"}' title='{lang="view_voters"}' class='ipsType_blendLinks' data-ipsTooltip data-ipsDialog data-ipsDialog-size="narrow" data-ipsDialog-title="{$choice}">
										{{else}}
											<span class='ipsFaded'>
										{{endif}}
											<i class='fa fa-user'></i> {$question['votes'][ $k ]}
										{{if $poll->canSeeVoters() && $question['votes'][ $k ] > 0}}
											</a>
										{{else}}
											</span>
										{{endif}}
									</div>
								</li>
							{{endforeach}}
						</ul>
					</li>
				{{endforeach}}
			</ol>
			{{if $poll->canVote() || !member.member_id || $poll->canClose() || ( ( $poll->poll_close_date instanceof \IPS\DateTime ) and !$poll->poll_closed ) || ( ( $poll->poll_close_date instanceof \IPS\DateTime ) and $poll->poll_closed )}}
				<hr class='ipsHr'>
				{{if $poll->poll_closed}}
					<p class="ipsType_reset ipsType_medium ipsType_unbold ipsMargin_vertical:half">
						<i class='fa fa-lock'></i> {lang="poll_closed_for_votes"}
					</p>
				{{endif}}
				<ul class='ipsToolList ipsToolList_horizontal ipsClearfix cPollButtons'>
					{{if $poll->canVote()}}
						<li class='ipsPos_left ipsResponsive_noFloat ipsToolList_primaryAction'>
							<a href="{$url->setQueryString( '_poll', 'form' )}" title='{lang="show_vote_options"}' class='ipsButton ipsButton_small ipsButton_light ipsButton_fullWidth' data-action='viewResults'><i class='fa fa-caret-left'></i> {lang="show_vote_options"}</a>
						</li>
					{{endif}}
					{{if !member.member_id}}
						<li class='ipsPos_left ipsResponsive_noFloat'>
							{lang="poll_guest" sprintf="\IPS\Http\Url::internal( 'app=core&module=system&controller=login', 'front', 'login' ), \IPS\Http\Url::internal( 'app=core&module=system&controller=register', 'front', 'register' )"}
						</li>
					{{endif}}
					{{if $poll->canClose()}}
						{{if ! $poll->poll_closed}}
							<li class='ipsPos_right ipsResponsive_noFloat'><a class='ipsButton ipsButton_link ipsButton_small ipsButton_fullWidth' href='{$url->setQueryString( array( 'do' => 'pollStatus', 'value' => 0 ) )->csrf()}'><i class="fa fa-lock"></i> {lang="poll_close"}</a></li>
						{{else}}
							<li class='ipsPos_right ipsResponsive_noFloat'><a class='ipsButton ipsButton_link ipsButton_small ipsButton_fullWidth' href='{$url->setQueryString( array( 'do' => 'pollStatus', 'value' => 1 ) )->csrf()}'><i class="fa fa-unlock"></i> {lang="poll_open"}</a></li>
						{{endif}}
					{{endif}}
					{{if ( $poll->poll_close_date instanceof \IPS\DateTime ) and !$poll->poll_closed}}
						<li class='ipsPos_right cPollCloseDate ipsResponsive_noFloat'><span class='ipsType_light ipsType_medium'>{lang="poll_auto_closes_on" sprintf="$poll->poll_close_date->localeDate(), $poll->poll_close_date->localeTime( FALSE )"}</span></li>
					{{elseif ( $poll->poll_close_date instanceof \IPS\DateTime ) and $poll->poll_closed}}
						<li class='ipsPos_right cPollCloseDate ipsResponsive_noFloat'><span class='ipsType_light ipsType_medium'>{lang="poll_auto_closed_on" sprintf="$poll->poll_close_date->localeDate(), $poll->poll_close_date->localeTime( FALSE )"}</span></li>
					{{endif}}
                </ul>
			{{endif}}
		</div>
	{{else}}
		<h2 class='ipsType_sectionTitle ipsType_reset'>
			<span class='ipsType_break ipsContained'>
				{$poll->poll_question}&nbsp;&nbsp;
				{{if $poll->votes}}<p class='ipsType_reset ipsPos_right ipsResponsive_hidePhone ipsType_light'><i class='fa fa-check-square-o'></i> {lang="poll_num_votes" pluralize="$poll->votes"}</p>{{endif}}
			</span>			
		</h2>
		<div class='ipsPadding ipsClearfix' data-role='pollContents'>
			{lang="no_permission_poll"}{{if !\IPS\Member::loggedIn()->member_id}} {lang="poll_guest" sprintf="\IPS\Http\Url::internal( 'app=core&module=system&controller=login', 'front', 'login' ), \IPS\Http\Url::internal( 'app=core&module=system&controller=register', 'front', 'register' )"}{{endif}}

            {{if $poll->canClose() || ( ( $poll->poll_close_date instanceof \IPS\DateTime ) and !$poll->poll_closed ) || ( ( $poll->poll_close_date instanceof \IPS\DateTime ) and $poll->poll_closed )}}
            <hr class='ipsHr'>
            <ul class='ipsToolList ipsToolList_horizontal ipsClearfix cPollButtons'>
                {{if $poll->canClose()}}
                    {{if !$poll->poll_closed}}
                        <li class='ipsPos_right ipsResponsive_noFloat'><a class='ipsButton ipsButton_link ipsButton_small ipsButton_fullWidth' href='{$url->setQueryString( array( 'do' => 'pollStatus', 'value' => 0 ) )->csrf()}'><i class="fa fa-lock"></i> {lang="poll_close"}</a></li>
                    {{else}}
                        <li class='ipsPos_right ipsResponsive_noFloat'><a class='ipsButton ipsButton_link ipsButton_small ipsButton_fullWidth' href='{$url->setQueryString( array( 'do' => 'pollStatus', 'value' => 1 ) )->csrf()}'><i class="fa fa-unlock"></i> {lang="poll_open"}</a></li>
                    {{endif}}
                {{endif}}

                {{if ( $poll->poll_close_date instanceof \IPS\DateTime ) and !$poll->poll_closed}}
                    <li class='ipsPos_right ipsResponsive_noFloat cPollCloseDate'><span class='ipsType_light ipsType_medium'>{lang="poll_auto_closes_on" sprintf="$poll->poll_close_date->localeDate(), $poll->poll_close_date->localeTime( FALSE )"}</span></li>
                {{elseif ( $poll->poll_close_date instanceof \IPS\DateTime ) and $poll->poll_closed}}
                    <li class='ipsPos_right ipsResponsive_noFloat cPollCloseDate'><span class='ipsType_light ipsType_medium'>{lang="poll_auto_closed_on" sprintf="$poll->poll_close_date->localeDate(), $poll->poll_close_date->localeTime( FALSE )"}</span></li>
                {{endif}}
            </ul>
            {{endif}}
        </div>
	{{endif}}
{{if !isset( \IPS\Request::i()->fetchPoll )}}
</section>
{{endif}}

