				<a href="{$row['_buttons']['delete']['link']}" {{if isset( $row['_buttons']['delete']['data'] )}}
					{{foreach $row['_buttons']['delete']['data'] as $k => $v}}
						data-{$k}="{$v}"
					{{endforeach}}
					{{endif}}><i class="fa fa-{$row['_buttons']['delete']['icon']}"></i></a>
			{{endif}}
