						{{if isset( $_SESSION['logged_in_as_key'] )}}{lang="switch_to_account" sprintf="$_SESSION['logged_in_from']['name']"}{{else}}{lang="sign_out"}{{endif}}
					</a>
				</li>
			</ul>
		</li>
	</ul>
{{else}}
	<ul id='elUserNav' class='ipsList_inline cSignedOut ipsResponsive_showDesktop'>
