        {{$login = new \IPS\Login( \IPS\Http\Url::internal( 'app=core&module=system&controller=login', 'front', 'login' ) );}}
		{{$usernamePasswordMethods = $login->usernamePasswordMethods();}}
        {{$buttonMethods = $login->buttonMethods();}}
        {{if $usernamePasswordMethods or $buttonMethods}}
            {{if \count( $usernamePasswordMethods ) OR \count( $buttonMethods ) > 1}}
            <li id='elSignInLink'>
                <a href='{url="app=core&module=system&controller=login" seoTemplate="login"}' data-ipsMenu-closeOnClick="false" data-ipsMenu id='elUserSignIn'>
                    {lang="sign_in"} &nbsp;<i class='fa fa-caret-down'></i>
                </a>
                {template="loginPopup" app="core" group="global" params="$login"}
            </li>
            {{else}}
            <li id='elSignInLink'>
                <a href='{url="app=core&module=system&controller=login" seoTemplate="login"}' id='elUserSignIn'>
                    {lang="sign_in"}
                </a>
            </li>
            {{endif}}
        {{endif}}
		{{if \IPS\Login::registrationType() != 'disabled'}}
