							<li class="ipsMenu_item"><a href="{url="app=core&module=members&controller=members&do=recountReputation&id={$member->member_id}" csrf="true"}" data-confirm data-confirmType="verify" data-confirmButtons='{expression="json_encode( array( 'yes' => \IPS\Member::loggedIn()->language()->addToStack('yes'), 'no' => \IPS\Member::loggedIn()->language()->addToStack('recount_all'), 'cancel' => \IPS\Member::loggedIn()->language()->addToStack('cancel') ) )" raw="true"}' data-confirmSubMessage="{lang="member_reputation_recount"}">{lang="recount"}</a></li>
