		<a href="{url="app=core&module=support&controller=errorLogs&do=settings"}" class="ipsButton ipsButton_light ipsButton_verySmall" data-ipsDialog data-ipsDialog-title="{lang="settings"}">{lang="settings"}</a>
	{{endif}}
</div>

{{if \count( $notifications )}}
	{{foreach $notifications as $notification}}
