	<span></span>
</span> <label for='{expression="preg_replace( '/\[(.+?)\]/', '[$1_unlimited]', $name, 1 )"}-unlimitedCheck' class='ipsField_unlimited' id='{expression="preg_replace( '/\[(.+?)\]/', '[$1_unlimited]', $name, 1 )"}_label'>{lang="never"}</label>

{{foreach output.globalSearchMenuOptions() as $type => $name}}
