	{{if ! $config['border']}}
	{{$block = \IPS\Request::i()->blockID;}}
	.ipsBox[data-blockid="{$block}"] {
		border: none;
		box-shadow: none;
	}
	.ipsWidget[data-blockid="{$block}"] {
		background: transparent !important;
	}
	{{endif}}
</style>
{{endif}}
{{if ! empty( $config['background_custom_image_overlay'] )}}
	{{$padding = isset( $config['style']['padding'] ) ? $config['style']['padding'] : '';}}
	{{unset( $config['style']['padding'] );}}
	{{$style = implode( " ", $config['style']);}}
{{else}}
	{{$style = implode( " ", $config['style']);}}
{{endif}}
<div class='{$config['class']} {{if ! empty($config['border'])}}ipsBox{{endif}}
			{{if  empty( $config['background_custom_image_overlay'] )}}{{if ! empty($config['padding']) and $config['padding'] == 'half'}}ipsPad_half{{elseif ! empty($config['padding']) and $config['padding'] == 'full'}}ipsPad{{endif}}{{endif}}
			{{if ! empty($config['fontsize']) and $config['fontsize'] != 'custom' and $config['fontsize'] != 'inherit'}}{$config['fontsize']}{{endif}}'
	 style='{{if ! empty($config['style'])}}{$style}{{endif}}'>
	{{if ! empty( $config['background_custom_image_overlay'] )}}
	<div class='{$config['class']}_overlay' style="background-color: {$config['background_custom_image_overlay']}; {$padding}"
		 class="{{if ! empty($config['padding']) and $config['padding'] == 'half'}}ipsPad_half{{elseif ! empty($config['padding']) and $config['padding'] == 'full'}}ipsPad{{endif}}">
	{{endif}}
	{$output|raw}
	{{if ! empty( $config['background_custom_image_overlay'] )}}
	</div>
	{{endif}}
</div>

{{if $title}}
	<h3 class="ipsType_reset ipsWidget_title">{$title}</h3>
{{endif}}
<section class="ipsWidget_inner">
	<ul class='ipsDataList ipsDataList_reducedSpacing'>
		{{foreach $clubs as $club}}
			<li class='ipsDataItem ipsClearfix'>
				<div class='ipsDataItem_icon'>
					{template="clubIcon" group="clubs" app="core" params="$club, 'tiny', 'ipsPos_left'"}
				</div>
				<div class='ipsDataItem_main'>
					<h3 class='ipsType_sectionHead ipsType_large ipsContained_container'>
						<span class='ipsContained ipsType_break'><a href='{$club->url()}'>{$club->name}</a></span>
					</h3>
					<p class='ipsType_reset ipsType_medium ipsType_light'>
						{lang="club_{$club->type}"}
						{{if $club->type !== $club::TYPE_PUBLIC}}
						&nbsp;&middot;&nbsp;
						{lang="club_members_count" pluralize="$club->members"}
						{{endif}}
					</p>
				</div>
			</li>
		{{endforeach}}
	</ul>
</section>

{template="includeJS" app="core" group="global" location="global" params=""}
{{$visibilityFields = array( 'show_on_all_devices', 'devices_to_show', 'clubs_visibility');}}
<form accept-charset='utf-8' class="ipsForm ipsForm_vertical" action="{$action}" method="post" {{if $uploadField}}enctype="multipart/form-data"{{endif}} {{foreach $attributes as $k => $v}}{$k}="{$v}"{{endforeach}} data-ipsForm>
	<input type="hidden" name="{$id}_submitted" value="1">
	{{foreach $hiddenValues as $k => $v}}
		<input type="hidden" name="{$k}" value="{$v}">
	{{endforeach}}
	{{if $uploadField}}
		<input type="hidden" name="MAX_FILE_SIZE" value="{$uploadField}">
		<input type="hidden" name="plupload" value="{expression="md5( mt_rand() )"}">
	{{endif}}
	<div class='ipsMenu_headerBar'>
		<h4 class='ipsType_sectionHead'>{lang="editBlockSettings"}</h4>
	</div>

	{{$hasSettings = FALSE;}}
	{{foreach $elements as $collection}}
		{{foreach $collection as $inputName => $input}}
			{{if \mb_substr( $inputName, 0, 12 ) != 'widget_adv__' and ! \in_array( $inputName, $visibilityFields )}}
				{{$hasSettings = TRUE; break 2;}}
			{{endif}}
		{{endforeach}}
	{{endforeach}}

	<div class='ipsTabs ipsClearfix ipsJS_show' id='tabs_{$id}' data-ipsTabBar data-ipsTabBar-contentArea='#ipsTabs_content_{$id}'>
		<a href='#tabs_{$id}' data-action='expandTabs'><i class='fa fa-caret-down'></i></a>
		<ul role='tablist'>
			{{if $hasSettings}}
			<li>
				<a href='#ipsTabs_tabs_{$id}_{$id}_tab_settings_panel' id='{$id}_tab_settings' class="ipsTabs_item" role="tab" aria-selected="true">
					{lang="settings"}
				</a>
			</li>
			{{endif}}
			<li>
				<a href='#ipsTabs_tabs_{$id}_{$id}_tab_visibility_panel' id='{$id}_tab_visibility' class="ipsTabs_item" role="tab" aria-selected="true">
					{lang="visibility"}
				</a>
			</li>
			{{if ( \in_array( 'IPS\Widget\Builder', class_implements( $widget ) ) )}}
			<li>
				<a href='#ipsTabs_tabs_{$id}_{$id}_tab_advanced_panel' id='{$id}_tab_advanced' class="ipsTabs_item" role="tab" aria-selected="false">
					{lang="widget_tab_advanced"}
				</a>
			</li>
			{{endif}}
		</ul>
	</div>
	<div id='ipsTabs_content_{$id}' class='ipsTabs_panels'>
		<div id='ipsTabs_tabs_{$id}_{$id}_tab_settings_panel' class="{{if $widget->menuStyle !== 'modal'}}ipsMenu_innerContent{{endif}} ipsTabs_panel ipsPad" aria-labelledby="{$id}_tab_settings" aria-hidden="false">
			<ul class='ipsList_reset'>
				{{foreach $elements as $collection}}
					{{foreach $collection as $inputName => $input}}
						{{if \mb_substr( $inputName, 0, 12 ) != 'widget_adv__' and ! \in_array( $inputName, $visibilityFields, TRUE )}}
							{{if \is_object( $input )}}
								{$input->rowHtml($form)|raw}
							{{else}}
								{$input|raw}
							{{endif}}
						{{endif}}
					{{endforeach}}
				{{endforeach}}
			</ul>
		</div>
		<div id='ipsTabs_tabs_{$id}_{$id}_tab_visibility_panel' class="{{if $widget->menuStyle !== 'modal'}}ipsMenu_innerContent{{endif}} ipsTabs_panel ipsPad" aria-labelledby="{$id}_tab_visibility" aria-hidden="false">
			<ul class='ipsList_reset'>
				{{foreach $elements as $collection}}
					{{foreach $collection as $inputName => $input}}
						{{if \is_object( $input ) and \in_array( $input->name, $visibilityFields, TRUE )}}
							{$input->rowHtml($form)|raw}
						{{elseif \in_array( $inputName, $visibilityFields, TRUE )}}
							{$input|raw}
						{{endif}}
					{{endforeach}}
				{{endforeach}}
			</ul>
		</div>

		{{if ( \in_array( 'IPS\Widget\Builder', class_implements( $widget ) ) )}}
		<div id='ipsTabs_tabs_{$id}_{$id}_tab_advanced_panel' class="{{if $widget->menuStyle !== 'modal'}}ipsMenu_innerContent{{endif}}ipsTabs_panel ipsPad" aria-labelledby="{$id}_tab_advanced" aria-hidden="false">
			<ul class='ipsList_reset'>
				{{foreach $elements as $collection}}
					{{foreach $collection as $inputName => $input}}
						{{if \mb_substr( $inputName, 0, 12 ) == 'widget_adv__' and ! \in_array( $inputName, $visibilityFields, TRUE )}}
							{{if \is_object( $input )}}
								{$input->rowHtml($form)|raw}
							{{else}}
								{$input|raw}
							{{endif}}
						{{endif}}
					{{endforeach}}
				{{endforeach}}
			</ul>
		</div>
		{{endif}}
	</div>
	<div class='ipsMenu_footerBar ipsType_center'>
		{{foreach $actionButtons as $button}}
			{$button|raw}
		{{endforeach}}
	</div>
</form>

{{if \count( $results )}}
	{{if $orientation == 'vertical'}}
		<ol class='ipsDataList ipsDataList_reducedSpacing cTopContributors'>
			{{$idx = 1;}}
			{{foreach $results as $memberId => $solvedCount}}
				{{$member = \IPS\Member::load( $memberId );}}
				<li class='ipsDataItem'>
					<div class='ipsDataItem_icon ipsPos_middle ipsType_center ipsType_large ipsType_light'><strong>{expression="$idx++"}</strong></div>
					<div class='ipsDataItem_main ipsPhotoPanel ipsPhotoPanel_tiny'>
						{template="userPhoto" app="core" group="global" params="$member, 'tiny'"}
						<div>
							{$member->link()|raw}
							<br>
							<span title="{lang="solved_badge_tooltip_time"}" data-ipsTooltip class='ipsRepBadge ipsRepBadge_positive'><i class='fa fa-check-circle'></i> {expression="\IPS\Member::loggedIn()->language()->formatNumber( $solvedCount )"}</span>
						</div>
					</div>
				</li>
			{{endforeach}}
		</ol>
	{{else}}
		<div class="ipsGrid ipsGrid_collapsePhone">
			{{$count = 0;}}
			{{foreach $results as $memberId => $solvedCount}}
				{{if $count == 4}}
					{{break;}}
				{{else}}
					{{$count++;}}
				{{endif}}
				{{$member = \IPS\Member::load( $memberId );}}
				<div class='ipsGrid_span3'>
					<div class='ipsPad_half ipsPhotoPanel ipsPhotoPanel_tiny'>
						{template="userPhoto" app="core" group="global" params="$member, 'tiny'"}
						<div>
							<p class='ipsType_reset ipsTruncate ipsTruncate_line'>
								{$member->link()|raw}
							</p>
							<span title="{lang="solved_badge_tooltip_time"}" data-ipsTooltip class='ipsRepBadge ipsRepBadge_positive'><i class='fa fa-check-circle'></i> {expression="\IPS\Member::loggedIn()->language()->formatNumber( $solvedCount )"}</span>
						</div>
					</div>
				</div>
			{{endforeach}}
		</div>
	{{endif}}
{{else}}
	<div class='ipsPad'>
		<p class='ipsType_reset'>{lang="top_solved_empty__{$timeframe}"}</p>
	</div>
{{endif}}

{{if ! \is_array( $images )}}
<div><img src="{$images}" class="ipsPageBuilderUpload"></div>
{{endif}}

{{if !empty( $similar ) }}
<h3 class='ipsWidget_title ipsType_reset'>{$title}</h3>

{{if $orientation == 'vertical'}}
	<div class='ipsWidget_inner'>
		<ul class='ipsDataList ipsDataList_reducedSpacing'>
			{{foreach $similar as $item}}
				{{$numComments = ( $item::$firstCommentRequired ) ? $item->mapped('num_comments') - 1 : $item->mapped('num_comments');}}
				<li class='ipsDataItem {{if $item->hidden()}} ipsModerated{{endif}}'>
					<div class='ipsDataItem_icon ipsPos_top'>
						{template="userPhoto" group="global" app="core" params="$item->author(), 'tiny'"}
					</div>
					<div class='ipsDataItem_main cWidgetComments'>
						<div class="ipsCommentCount ipsPos_right {{if $numComments === 0}}ipsFaded{{endif}}" data-ipsTooltip title='{lang="replies_number" pluralize="$numComments"}'>{expression="\IPS\Member::loggedIn()->language()->formatNumber($numComments)"}</div>

						<div class='ipsType_break ipsContained'>
							{{if $item->mapped('featured') || $item->hidden() === -1 || $item->hidden() === 1 || \IPS\IPS::classUsesTrait( $item, 'IPS\Content\Solvable' )}}
								{{if $item->hidden() === -1}}
									<span><span class="ipsBadge ipsBadge_icon ipsBadge_small ipsBadge_warning" data-ipsTooltip title='{$item->hiddenBlurb()}'><i class='fa fa-eye-slash'></i></span></span>
								{{elseif $item->hidden() === 1}}
									<span><span class="ipsBadge ipsBadge_icon ipsBadge_small ipsBadge_warning" data-ipsTooltip title='{lang="pending_approval"}'><i class='fa fa-warning'></i></span></span>
								{{endif}}
								{{if $item->mapped('featured')}}
									<span><span class="ipsBadge ipsBadge_icon ipsBadge_small ipsBadge_positive" data-ipsTooltip title='{lang="featured"}'><i class='fa fa-star'></i></span></span>
								{{endif}}
								{{if \IPS\IPS::classUsesTrait( $item, 'IPS\Content\Solvable' ) and $item->isSolved()}}
									<span><span class="ipsBadge ipsBadge_icon ipsBadge_small ipsBadge_positive" data-ipsTooltip title='{lang="this_is_solved"}'><i class='fa fa-check'></i></span></span>
								{{endif}}
							{{endif}}							
							<a href="{$item->url( "getPrefComment" )}" title='{lang="view_this_topic" sprintf="$item->title"}' class='ipsDataItem_title'>{$item->mapped('title')}</a>
						</div>
						<p class='ipsType_reset ipsType_medium ipsType_blendLinks ipsContained'>
							<span>{lang="byline_nodate" htmlsprintf="$item->author()->link( NULL, NULL, $item->isAnonymous() )"}</span><br>
							<span class='ipsType_light'>{lang="started_date" htmlsprintf="\IPS\DateTime::ts( $item->mapped('date') )->html()"}</span>
						</p>
					</div>
				</li>
			{{endforeach}}
		</ul>
	</div>
{{else}}
	<div class='ipsWidget_inner'>
		<ul class='ipsDataList'>
			{{foreach $similar as $item}}
				<li class="ipsDataItem ipsDataItem_responsivePhoto {{if $item->hidden()}}ipsModerated{{endif}}">
					<div class='ipsDataItem_main'>
						<h4 class='ipsDataItem_title ipsContained_container'>
							{{if $item->mapped('pinned') || $item->mapped('featured') || $item->hidden() === -1 || $item->hidden() === 1 || \IPS\IPS::classUsesTrait( $item, 'IPS\Content\Solvable' )}}
								{{if $item->hidden() === -1}}
									<span><span class="ipsBadge ipsBadge_icon ipsBadge_small ipsBadge_warning" data-ipsTooltip title='{$item->hiddenBlurb()}'><i class='fa fa-eye-slash'></i></span></span>
								{{elseif $item->hidden() === 1}}
									<span><span class="ipsBadge ipsBadge_icon ipsBadge_small ipsBadge_warning" data-ipsTooltip title='{lang="pending_approval"}'><i class='fa fa-warning'></i></span></span>
								{{endif}}							
								{{if $item->mapped('pinned')}}
									<span><span class="ipsBadge ipsBadge_icon ipsBadge_small ipsBadge_positive" data-ipsTooltip title='{lang="pinned"}'><i class='fa fa-thumb-tack'></i></span></span>
								{{endif}}
								{{if $item->mapped('featured')}}
									<span><span class="ipsBadge ipsBadge_icon ipsBadge_small ipsBadge_positive" data-ipsTooltip title='{lang="featured"}'><i class='fa fa-star'></i></span></span>
								{{endif}}
								{{if \IPS\IPS::classUsesTrait( $item, 'IPS\Content\Solvable' ) and $item->isSolved()}}
									<span><span class="ipsBadge ipsBadge_icon ipsBadge_small ipsBadge_positive" data-ipsTooltip title='{lang="this_is_solved"}'><i class='fa fa-check'></i></span></span>
								{{endif}}
							{{endif}}
							{{if $item->prefix()}}
								<span>{template="prefix" group="global" app="core" params="$item->prefix( TRUE ), $item->prefix()"}</span>
							{{endif}}

							<span class='ipsType_break ipsContained'>
								<a href='{$item->url( "getPrefComment" )}' {{if $item->tableHoverUrl and $item->canView()}}data-ipsHover data-ipsHover-target='{$item->url()->setQueryString('preview', 1)}' data-ipsHover-timeout='1.5' {{endif}}>
									{$item->mapped('title')}
								</a>
							</span>
							{{if $item->commentPageCount() > 1}}
								{$item->commentPagination( array(), 'miniPagination' )|raw}
							{{endif}}
						</h4>

						<p class='ipsType_reset ipsType_medium ipsType_light'>
							{lang="byline" htmlsprintf="$item->author()->link( NULL, NULL, $item->isAnonymous() )"} {datetime="$item->mapped('date')"}
						</p>
						{{if \count( $item->tags() )}}
							&nbsp;&nbsp;
							{template="tags" group="global" app="core" params="$item->tags(), true, true"}
						{{endif}}
					</div>
					<ul class='ipsDataItem_stats'>
						{{foreach $item->stats(FALSE) as $k => $v}}
							<li {{if \in_array( $k, $item->hotStats )}}class="ipsDataItem_stats_hot" data-text='{lang="hot_item"}' data-ipsTooltip title='{lang="hot_item_desc"}'{{endif}}>
								<span class='ipsDataItem_stats_number'>{number="$v"}</span>
								<span class='ipsDataItem_stats_type'>{lang="{$k}" pluralize="$v"}</span>
							</li>
						{{endforeach}}
					</ul>
					<ul class='ipsDataItem_lastPoster ipsDataItem_withPhoto'>
						<li>
							{{if $item->mapped('num_comments')}}
								{template="userPhoto" app="core" group="global" params="$item->lastCommenter(), 'tiny'"}
							{{else}}
								{template="userPhoto" app="core" group="global" params="$item->author(), 'tiny'"}
							{{endif}}
						</li>
						<li>
							{{if $item->mapped('num_comments')}}
								{$item->lastCommenter()->link()|raw}
							{{else}}
								{$item->author()->link( NULL, NULL, $item->isAnonymous() )|raw}
							{{endif}}
						</li>
						<li class="ipsType_light">
							<a href='{$item->url( 'getLastComment' )}' title='{lang="get_last_post"}' class='ipsType_blendLinks'>
								{{if $item->mapped('last_comment')}}{datetime="$item->mapped('last_comment')"}{{else}}{datetime="$item->mapped('date')"}{{endif}}
							</a>
						</li>
					</ul>
				</li>
			{{endforeach}}
		</ul>
	</div>
{{endif}}
{{endif}}

{{if \count( $results )}}
	{{if $orientation == 'vertical'}}
		<ol class='ipsDataList ipsDataList_reducedSpacing cTopContributors'>
			{{$idx = 1;}}
			{{foreach $results as $memberId => $rep}}
				{{$member = \IPS\Member::load( $memberId );}}
				<li class='ipsDataItem'>
					<div class='ipsDataItem_icon ipsPos_middle ipsType_center ipsType_large ipsType_light'><strong>{expression="$idx++"}</strong></div>
					<div class='ipsDataItem_main ipsPhotoPanel ipsPhotoPanel_tiny'>
						{template="userPhoto" app="core" group="global" params="$member, 'tiny'"}
