				<a href="{url="app=core&module=discover&controller=popular&tab=leaderboard&{$_timeframe}" seoTemplate="leaderboard_leaderboard"}" class='ipsButton ipsButton_small ipsButton_light ipsButton_fullWidth'>{lang="leaderboard_show_more"}</a>
