			margin: 0 auto;
		}

	html[dir] .cGuestTeaser_left {
		border-left: 0;
		border-right: 0;
		border-bottom: 2px solid rgba( var(--theme-text_dark), 0.05 );
		margin-bottom: 15px;
		padding-bottom: 15px;
	}

	/* Reset guest teaser on mobile back to normal layout from tablet flex layout */
	.cGuestTeaser .ipsGrid {
		display: block !important;
	}
