/* Select trees */
.ipsSelectTree{
	min-height: 40px;
	background: #fff;
	background: var(--input--background);
	border-color: rgba(24, 45, 70, 0.22);
	border-radius: 4px;
	padding: 10px 25px 10px 10px;
	color: inherit;
	box-shadow: rgba(44, 95, 140, 0.08) 0px 3px 4px -1px;
	box-shadow: var(--input--shadow) 0px 3px 4px -1px;
	border-color: var(--input--border);
}

	html[dir='rtl'] .ipsSelectTree{
