	color: #f8e5d4;
}

	.ipsDarkMode .ipsFieldRow.ipsFieldRow_searchResult .ipsFieldRow_desc{
		color: #c3b899;
	}

		.ipsDarkMode .ipsFieldRow_searchResult .ipsFieldRow_desc a{
			color: inherit;
