/* NEW FEATURES TOUR */
.acpNewFeature {
	position: fixed;
	left: 0;
	top: 0;
	right: 0;
	bottom: 0;
	display: flex;
	align-items: center;
	justify-content: center;
	pointer-events: none;
}

.acpNewFeature_wrap {
	width: 340px;
	height: 475px;
	background: #fff;
	background: var(--c1);
	border-radius: 3px;
	box-shadow: 0px 5px 35px rgba(0,0,0,0.1);
	position: relative;
	pointer-events: auto;
}

	.acpNewFeature_inner {
		position: absolute;
		padding: 20px;
		top: 0;
		left: 0;
		right: 0;
		bottom: 0;
		overflow: hidden;
	}

.acpNewFeature_mainTitle {
	font-size: 17px;
	color: #4c4c4c;
	color: var(--c7);
	font-weight: 400;
	text-align: center;
	margin: 0;
}

.acpNewFeature_cardWrap {
	margin: 20px 0;
	position: relative;
}

	.acpNewFeature_card {
		position:absolute;
		top: 0;
		left: 0;
		right: 0;
		bottom: 0;
	}

.acpNewFeature_dots {
	text-align: center;
	position: absolute;
	bottom: 10px;
	left: 20px;
	right: 20px;
}

	.acpNewFeature_dot {
		display: inline-block;
	}

	.acpNewFeature_dot > a {
		display: block;
		border: 1px solid #3D6594;
		border-color: var(--primary);
		border-radius: 11px;
		width: 11px;
		height: 11px;
		margin-right: 2px;
	}

		.acpNewFeature_dot.acpNewFeature_active > a {
