			background: var(--primary);
		}

	.acpNewFeature_dot:last-child > a {
		margin-right: 0;
	}

.acpNewFeature_info {
	text-align: center;
}

.acpNewFeature_title {
	text-align: center;
	font-size: 17px;
	margin-bottom: 0;
	margin-top: 20px;
}

.acpNewFeature_desc {
	text-align: center;
	font-size: 14px;
	margin-top: 10px;
	opacity: 0.8;
	max-height: 150px;
	overflow-y: auto;
}

.acpNewFeature_image {
	width: 340px;
	height: 150px;
	margin-left: -20px;
	background: #f0f0f0;
	background: var(--c3);
	border-top: 1px solid rgba(0,0,0,0.1);
	border-bottom: 1px solid rgba(0,0,0,0.1);
}

.acpNewFeature_close {
	background: #111;
	color: #fff;
	font-family: 'arial', sans-serif;
	font-size: 19px;
	font-weight: 300;
	width: 30px;
	height: 30px;
	border-radius: 30px;
	line-height: 30px;
	display: block;
	position: absolute;
	top: -10px;
	right: -10px;
	text-align: center;
	z-index: 100;
}

	.ipsDarkMode .acpNewFeature_close {
		background: var(--c5);
	}

	.acpNewFeature_close:hover {
		color: #fff;
	}

.acpNewFeature_arrow {
	font-size: 50px;
	color: #fff;
	position: absolute;
	top: 50%;
