.ipsSideMenu_itemActive a,
a.ipsSideMenu_itemActive,
.ipsSideMenu_withChecks .ipsSideMenu_item > input[type="checkbox"]:checked ~ a,
.ipsSideMenu_withRadios .ipsSideMenu_item > input[type="radio"]:checked ~ a {
	background: #3b6c99;
	background: var(--primary);
	color: #fff;
}

.ipsSideMenu_item:not(.ipsSideMenu_itemActive) a:hover,
a.ipsSideMenu_item:not(.ipsSideMenu_itemActive):hover,
span.ipsSideMenu_item:not(.ipsSideMenu_itemActive):hover{
	background: #c8d0d9;
	background: var(--c1);
}

.ipsSideMenu_itemDisabled a, 
a.ipsSideMenu_itemDisabled,
span.ipsSideMenu_itemDisabled{
	color: var(--c5);
	opacity: .4;
}

.ipsSideMenu_itemActive .ipsSideMenu_itemCount{
	background: transparent;
	color: inherit;
}

.ipsSideMenu_list > li:last-child .ipsSideMenu_item a, 
.ipsSideMenu_list > li:last-child a.ipsSideMenu_item {
	margin-bottom: 0;
}

.ipsMenu_title{
	background: #edf0f5;
	background: var(--c2);
	color: var(--c9);
}

.ipsMenu_item > a:not(.ipsMenu_itemInline),
.ipsMenu_item > span:not(.ipsMenu_itemInline){
	color: var(--c7);
}

.ipsMenu_sep{
	border-color: var(--c4);
}

/* Auto complete */
.ipsAutocompleteMenu{
	background: var(--c0);
}

	.ipsAutocompleteMenu_item[data-selected]{
		background: var(--c2);
	}

/* Dark mode selectors */
.ipsMenu_selectable .ipsMenu_item:not( .ipsMenu_itemNonSelect ) a:before, 
.ipsMenu_selectable .ipsMenu_item:not( .ipsMenu_itemNonSelect ) > span:before, 
.ipsMenu_selectable .ipsMenu_item:not( .ipsMenu_itemNonSelect ) button:before {
	color: var(--c4);
}

.ipsBox,
.acpBlock,
#acpContent > form[class^="ipsForm"],
.ipsChart,
.ipsWizard,
.acpBlock .ipsTabs_panel > .acpBlock,
#elLogin_box{
	box-shadow: none;
	border-radius: 5px;
	background: #fff;
	background: var(--c0);
	border-width: 0;
}

.ipsBox:not( .ipsBox_transparent ):not( .ipsModerated ) {
	background: #fff;
	background: var(--c0);
}

.acpFormTabContent{
	background: #fff;
	background: var(--c0);
	padding: 1px;
}

/* Comments */
.ipsComment{
	background-color: var(--c1);
}

/* Moderated content */
.ipsDarkMode .ipsModerated:not(.ipsComment_selected):not(.ipsDataItem_selected) {
	background-color: #4b3333;
	color: #e2bfbf;
}

	.ipsDarkMode .ipsModerated a {
		color: inherit;
	}

	.ipsDarkMode .ipsModerated .ipsType_light {
		color: {hextorgb="#e2bfbf" opacity="0.7"};
	}

/* The pseudo elements purposely prevent child margins from collapsing */
.ipsBox::before,
.ipsBox::after,
.ipsWizard::before,
.ipsWizard::after,
.acpBlock::before,
.acpBlock::after{
	content: '';
	display: block;
	height: 0.1px;
}

/* Darker box-shadow for login box */
#elLogin_box{
	box-shadow: 0px 20px 40px -10px rgba(28,35,49,0.15), 0px 0px 0px 1px rgba(28,35,49,0.05);
}

	/* Remove styles from children boxes */
	.ipsDialog_content > .acpBlock,
	.acpBlock > .acpBlock,
	.ipsBox > .acpBlock,
	.ipsBox .ipsChart {
		box-shadow: none;
	}

.ipsBox_shadowed {
	border: 1px solid rgba(0,0,0,0.12);
	box-shadow: 0 2px 4px 0 rgba(0,0,0,0.04);
}

		.ipsDarkMode .ipsBox_shadowed {
			border-color: rgba(255,255,255,0.1) transparent transparent transparent;
		}

.ipsBox_group {
	border: 1px solid rgba(0,0,0,0.1);
	border-radius: 4px;
	background: rgba(0,0,0,0.033);
}

.ipsBox_title {
	font-size: 12px;
	font-weight: 500;
	text-transform: uppercase;
	color: rgba(0,0,0,0.7);
	color: var(--c5);
	padding: 10px 15px 5px 0;
	margin: 0;
}

	.ipsBox_title + .ipsBox {

	}

.ipsBox_titleBar {
	font-size: 15px;
	font-weight: 600;
	padding: var(--sp-5);
	margin: 0;
	color: var(--text-heavy);
}

	.ipsBox_titleBar .ipsBox_titleBar__icon{
		color: #587898;
		color: var(--text-soft);
		width: 1.5em;
		font-size: .9em;
	}

	.ipsBox_titleBar a.ipsPos_right {
		font-weight: normal;
	}

.acpWidgetToolbar {
	padding: 10px;
	position: relative;
}

	.acpWidgetToolbar .ipsPagination {
		line-height: 30px;
		margin-top: 2px;
	}

.ipsApp input[type="text"].acpTable_search {
	max-width: 200px;
}
html[dir="ltr"] .ipsApp input[type="text"].acpTable_search {
	padding-right: 30px;
}
html[dir="rtl"] .ipsApp input[type="text"].acpTable_search {
	padding-left: 30px;
}
	/*
	.ipsApp input[type="text"].acpTable_search:hover,
	.ipsApp input[type="text"].acpTable_search:focus {
		background: #fff;
	}*/

.acpWidgetSearch {
	padding: 0 10px;
	line-height: 41px;
	color: rgba(0,0,0,0.4);
	color: var(--c6);
	border: 0px solid transparent;
	position: relative;
}
html[dir="ltr"] .acpWidgetSearch {
	margin-left: -30px;
}
html[dir="rtl"] .acpWidgetSearch {
	margin-right: -30px;
}

	.acpWidgetSearch:hover {
		color: #000;
		color: var(--c9);
	}

/* Info panels */
.cWithInfoPanel {
	display: flex;
}

.cWithInfoPanel_main {
	flex-grow: 1;
	order: 1;
	margin-right: 30px;
	min-width: 0;
}

	.cWithInfoPanel_info.ipsSticky ~ .cWithInfoPanel_main {
		margin-right: 350px;
	}

.cWithInfoPanel_info {
	background: #2E3D49;
	min-width: 350px;
	max-width: 350px;
	order: 2;
	overflow: auto;
}

	html[dir='ltr'] .cWithInfoPanel_info{
		margin: 0 -15px -15px 0;
		border-top-left-radius: 5px;
	}
	html[dir='rtl'] .cWithInfoPanel_info{
		margin: 0 0 -15px -15px;
		border-top-right-radius: 5px;
	}

	.cWithInfoPanel_info.ipsSticky {
		top: 0;
		right: 0;
		bottom: 0;
		margin: 0;
	}

.cWithInfoPanel .ipsType_sectionTitle {
	margin: -15px -15px 15px -15px;
	background: #27333D;
	padding: 10px 15px;
	color: #fff;
	font-weight: 300;
}

/* Charts */
.ipsChart_filters {
	border-radius: 5px;
}

.acpContent > .ipsChart .ipsChart_filters{
	background-image: linear-gradient(to bottom, rgba(255,255,255,1), rgba(255,255,255,0));
}

	ul[data-role='filterSaveMenu'] ul.ipsToolList,
	ul[data-role='filterRenameMenu'] ul.ipsToolList {
		margin-bottom: 0px;
	}

	button[data-role="renameChart"] {
		margin-right: 4px;
	}

	/* Align buttons correctly in dashboard */
	.ipsChart_filters .ipsButton{ vertical-align: top; }

/* Apple pie chart */
.ipsPieBar__bar {
	height: 38px;
	background: #ddd;
	overflow: hidden;
	white-space: nowrap;
	display: flex;
	border-radius: 5px;
	position: relative;
}

.ipsPieBar__barSegment {
	height: 38px;
}

.ipsList_inline > .ipsPieBar__legendItem {
	display: inline-flex;
	align-items: center;
}

.ipsPieBar__barSegment:nth-child(10n-9),
.ipsPieBar__legendItem:nth-child(10n-9) > .ipsPieBar__legendItemKey {
	background: #10967e;
}
.ipsPieBar__barSegment:nth-child(10n-8),
.ipsPieBar__legendItem:nth-child(10n-8) > .ipsPieBar__legendItemKey {
	background: #ea7963;
}
.ipsPieBar__barSegment:nth-child(10n-7),
.ipsPieBar__legendItem:nth-child(10n-7) > .ipsPieBar__legendItemKey {
	background: #de6470;
}
.ipsPieBar__barSegment:nth-child(10n-6),
.ipsPieBar__legendItem:nth-child(10n-6) > .ipsPieBar__legendItemKey {
	background: #6b9dde;
}
.ipsPieBar__barSegment:nth-child(10n-5),
.ipsPieBar__legendItem:nth-child(10n-5) > .ipsPieBar__legendItemKey {
	background: #b09be4;
}
.ipsPieBar__barSegment:nth-child(10n-4),
.ipsPieBar__legendItem:nth-child(10n-4) > .ipsPieBar__legendItemKey {
	background: #eec766;
}
.ipsPieBar__barSegment:nth-child(10n-3),
.ipsPieBar__legendItem:nth-child(10n-3) > .ipsPieBar__legendItemKey {
	background: #9fc973;
}
.ipsPieBar__barSegment:nth-child(10n-2),
.ipsPieBar__legendItem:nth-child(10n-2) > .ipsPieBar__legendItemKey {
	background: #e291bf;
}
.ipsPieBar__barSegment:nth-child(10n-1),
.ipsPieBar__legendItem:nth-child(10n-1) > .ipsPieBar__legendItemKey {
	background: #55c1a6;
}
.ipsPieBar__barSegment:nth-child(10n),
.ipsPieBar__legendItem:nth-child(10n) > .ipsPieBar__legendItemKey {
	background: #5fb9da;
}

.ipsPieBar__legend {
	text-align: left;
    margin-top: 10px;
}

.ipsPieBar__legendItemKey {
	display: inline-block;
	width: 14px;
	height: 14px;
	margin-right: 4px;
	border-radius: 5px;
}

/* Step bar */
.ipsStepBar{
	background: var(--c2);
	color: var(--c7);
	margin: 5px;
	border-radius: 5px;
}

.ipsStepBar > .ipsStep > a,
.ipsStepBar > .ipsStep > span{
	color: var(--c7);
}

.ipsStepBar > .ipsStep.ipsStep_active::before,
.ipsStepBar > .ipsStep.ipsStep_active::after{
	background: var(--dark);
}

.ipsStepBar > .ipsStep::before,
.ipsStepBar > .ipsStep::after,
.ipsStepBar > .ipsStep + .ipsStep.ipsStep_active::after{
	border-color: var(--c0);
}

	.ipsDarkMode .ipsStepBar > .ipsStep::before,
	.ipsDarkMode .ipsStepBar > .ipsStep::after,
	.ipsDarkMode .ipsStepBar > .ipsStep + .ipsStep.ipsStep_active::after {
		border-color: var(--c4);
	}

/* Loading */
.icon-spinner2:before,
.ipsLoading:before{
	border-color: var(--c2);
	border-top-color: var(--c7);
}

/* Stats bar */
.acpStatsBar {
	height: 38px;
	background: #ddd;
	overflow: hidden;
	white-space: nowrap;
	display: flex;
	border-radius: 5px;
	position: relative;
}

	.acpStatsBar::after{
		content: '';
		position: absolute;
		top: 0; left: 0; right: 0; bottom: 0;
		border: 1px solid rgba(0,0,0,0.1);
		border-radius: inherit;
		pointer-events: none;
	}

	.acpStatsBar_segment,
	.acpStatsBar_subsegment {
		height: 38px;
	}

	.acpStatsBar_subsegment {
		background: rgba(0,0,0,0.2);
	}

	.ipsList_inline > .acpStatsBar_legend{
		display: inline-flex;
		align-items: center;
	}

	.acpStatsBar_segment:nth-child(10n-9),
	.acpStatsBar_legend:nth-child(10n-9) > .acpStatsBar_preview {
		background: #10967e;
	}
	.acpStatsBar_segment:nth-child(10n-8),
	.acpStatsBar_legend:nth-child(10n-8) > .acpStatsBar_preview {
		background: #ea7963;
	}
	.acpStatsBar_segment:nth-child(10n-7),
	.acpStatsBar_legend:nth-child(10n-7) > .acpStatsBar_preview {
		background: #de6470;
	}
	.acpStatsBar_segment:nth-child(10n-6),
	.acpStatsBar_legend:nth-child(10n-6) > .acpStatsBar_preview {
		background: #6b9dde;
	}
	.acpStatsBar_segment:nth-child(10n-5),
	.acpStatsBar_legend:nth-child(10n-5) > .acpStatsBar_preview {
		background: #b09be4;
	}
	.acpStatsBar_segment:nth-child(10n-4),
	.acpStatsBar_legend:nth-child(10n-4) > .acpStatsBar_preview {
		background: #eec766;
	}
	.acpStatsBar_segment:nth-child(10n-3),
	.acpStatsBar_legend:nth-child(10n-3) > .acpStatsBar_preview {
		background: #9fc973;
	}
	.acpStatsBar_segment:nth-child(10n-2),
	.acpStatsBar_legend:nth-child(10n-2) > .acpStatsBar_preview {
		background: #e291bf;
	}
	.acpStatsBar_segment:nth-child(10n-1),
	.acpStatsBar_legend:nth-child(10n-1) > .acpStatsBar_preview {
		background: #55c1a6;
	}
	.acpStatsBar_segment:nth-child(10n),
	.acpStatsBar_legend:nth-child(10n) > .acpStatsBar_preview {
		background: #5fb9da;
	}

	.acpStatsBar_preview {
		display: inline-block;
		width: 14px;
		height: 14px;
		margin-right: 4px;
		border-radius: 5px;
	}


/* Progress bars */
.ipsProgressBar{
	background: var(--c3);
}

	.ipsProgressBar_progress{
		background: var(--primary);
	}

/* Pixabay modal */
.ipsPixabay_thumb{
	background-color: var(--c1);
}

/* Comment count */
.ipsCommentCount{
	background: var(--c3);
	color: var(--c9);
}

/* Thumbs */
.ipsThumb {
	border-color: var(--c2);
}
	.ipsThumb_bg {
		background-color: var(--c2);
	}

.ipsPagination{
	color: var(--text-soft);
}

.ipsPagination .ipsPagination_page.ipsPagination_active a {
	background: var(--primary);
}

[data-role="pageJump"] .ipsButton{
	margin-top: 10px;
}

.ipsPager{
	color: var(--c7);
}

	.ipsPager_prev a:hover,
	.ipsPager_next a:hover{
		color: var(--c9);
	}

.ipsAlert,
.ipsDialog > div,
.ipsDialog .ipsDialog_loading{
	background: var(--c0);
}

.ipsModal {
	background: rgba(69,88,107,0.5);
}

.ipsDialog > div {
	box-shadow: 0px 5px 35px rgba(69,88,107,0.4);
	border-radius: 5px;
	background: var(--c0);
}

		.ipsDarkMode .ipsModal{
			background: rgba(0,0,0,0.6);
		}
		.ipsDarkMode .ipsDialog > div{
			box-shadow: 0px 5px 35px rgba(0,0,0,0.4);
		}

.ipsDialog_title {
	font-size: 23px;
	color: var(--c8);
}

.ipsDialog_close{
	color: inherit !important;
}

.ipsMenu {
	background: var(--c1);
	border-color: var(--c3);
}

	.ipsMenu_item > a, 
	.ipsMenu_item > span {
		color: var(--c5);
	}

	.ipsMenu.ipsMenu_topLeft:after,
	.ipsMenu.ipsMenu_topRight:after,
	.ipsMenu.ipsMenu_topCenter:after{
		border-top-color: var(--c1);
	}

	.ipsMenu.ipsMenu_bottomRight:after,
	.ipsMenu.ipsMenu_bottomLeft:after,
	.ipsMenu.ipsMenu_bottomCenter:after{
		border-bottom-color: var(--c1);
	}


.ipsDialog_content .ipsForm {
	margin: 15px;
}

.pac-container {
	z-index: 2000;
}

/* ACP Date pickers */
.ui-datepicker {
	background: var(--c1);
}

.ui-datepicker-header {
	background: var(--dark);
	color: #fff;
	border-bottom-width: 0;
}

	.ipsDarkMode .ui-datepicker-header{
		--input--shadow: transparent;
	}
	.ui-datepicker-title{
		line-height: 1;
	}
		.ui-datepicker-title select{
			margin: 5px;
		}

.ui-datepicker-prev:after, .ui-datepicker-next:after {
	color: #fff;
}
.ui-datepicker th {
	background: var(--c2);
}

.ui-datepicker td a{
	border-radius: 4px;
}

.ui-datepicker td a:hover {
	background-color: var(--c3);
}

.ui-datepicker-current-day {
	background-color: transparent;
	font-weight: bold;
}
	.ui-datepicker-current-day a{
		background: var(--c2);
	}

	.ui-datepicker-title select,
	.ui-datepicker-title option {
		color: var(--c8);
	}

	.ipsDarkMode .ui-datepicker-title select,
	.ipsDarkMode .ui-datepicker-title option {
		color: inherit;
	}

.cSupportQuery {
	border: 0 !important;
	white-space: pre-wrap;
}

.ipsTable{
	background: #fff;
	background: var(--c0);
}

.ipsTable th {
	text-transform: uppercase;
	font-size: 11px;
	font-weight: 500;
	border-bottom: 1px solid rgba(0,0,0,0.05);
}
html[dir="ltr"] .ipsTable th {
	padding: 11px 20px 11px 10px;
}
html[dir="rtl"] .ipsTable th {
	padding: 11px 10px 11px 20px;
}

.ipsTable_sortable.ipsTable_sortableActive {
	background: #e0e5ee;
	background: var(--c4);
	color: inherit;
}

	.ipsTable_sortable .ipsTable_sortIcon:after,
	.ipsTable_sortable.ipsTable_sortableActive .ipsTable_sortIcon::after{
		color: inherit;
	}

.ipsTable.ipsMatrix thead th {
	background: #f5f7fb;
	background: var(--c2);
	color: inherit;
}
html[dir="ltr"] .ipsTable.ipsMatrix thead th {
	padding-left: 15px;
}
html[dir="rtl"] .ipsTable.ipsMatrix thead th {
	padding-right: 15px;
}

.ipsTable td {
	border-bottom-color: #ebebeb;
	border-bottom-color: var(--c2);
}

.ipsTable_sortable:not(.ipsTable_sortableActive):hover{
	background: rgba(0,0,0,0.02);
}

.ipsTable_zebra tbody tr:nth-child(2n):not(.ipsTable_highlight):not(.ipsModerated){
	background: #f6f8fa;
	background: var(--c1);
}

.ipsTable.ipsMatrix .ipsMatrix_subHeader {
	background: var(--c3);
	color: var(--c8);
}

.ipsTable.ipsMatrix .ipsMatrix_buttons {
	margin-top: 5px;
}

.ipsTabs {
	--ipsTabs--padding: 4px;
	background: #f5f7fb;
	background: var(--c3);
	color: var(--c7);
	box-shadow: inset rgba(0,0,0,0.03) 0px -1px 2px;
}

.ipsTabs_small{
	border-width: 0;
}

.ipsTabs_item{
	margin-right: 3px;
	border-radius: 3px 3px 0 0;
}

.ipsTabs.ipsTabs_small .ipsTabs_item{
	line-height: 36px;
	font-size: 13px;
}

.ipsTabs_item:not( .ipsTabs_activeItem ) {
	color: inherit;
	background: transparent;
	border-top: 2px solid transparent;
}

	.ipsTabs_item:not( .ipsTabs_activeItem ):hover {
		color: rgba(0,0,0,0.8);
		color: var(--c9);
	}

		.ipsDarkMode .ipsTabs_item:not( .ipsTabs_activeItem ):hover {
			background: rgba(255,255,255,0.04);
		}

body .ipsTabs_activeItem {
	background: #fff;
	background: var(--c0);
	color: #3b6c99 !important;
	color: var(--c9) !important;
	font-weight: bold;
	border-top: 2px solid #3b6c99;
	border-top-color: currentColor;
}

	.ipsTabs_activeItem:hover{
		color: var(--c9);
	}

/* Remove background since it's already assigned with .ipsBox */
.ipsTabs_panel{
	background-color: transparent;
}

/* Don't apply above to forms when they're the only thing in a tab, though */ 
.ipsTabs_panel > .ipsForm,
.ipsTabs_panel div[data-controller="core.global.core.table"],
.ipsTabs_panel .acpTrees_buttons + .acpBlock,
.ipsTabs_panel .ipsForm,
.ipsTabs_panel .ipsChart {
	margin: 10px;
}

	.ipsTabs_panel .ipsTabs_panel .ipsChart {
		margin: 0;
		border: 0;
		box-shadow: none;
	}

.ipsTabs_panel *:not( [data-controller="core.global.core.table"] ) .ipsToolList {
	padding: 10px 10px 0 10px;
}

	.ipsTabs_panel > .ipsForm *:not( [data-controller="core.global.core.table"] ) .ipsToolList,
	.ipsTabs_panel div[data-controller="core.global.core.table"] .ipsToolList {
		padding: 0;
	}

.ipsTabs_panel .acpBlock {
	border: 0;
	padding: 0;
	box-shadow: none;
}

/* Dark tabs */
.ipsTabs.ipsTabs_alt {
	background: #2E3D49;
}

	.ipsTabs.ipsTabs_alt .ipsTabs_item:not( .ipsTabs_activeItem ) {
		background: rgba(255,255,255,0.1);
		color: rgba(255,255,255,0.8);
	}

/* Vertical tabs */
.ipsTabs.ipsTabs_vertical {
	padding: 2px 0 2px 2px;
}

.ipsTabs.ipsTabs_vertical > ul {
	display: flex;
	flex-direction: column;
	width: 50px;
}

	.ipsTabs.ipsTabs_vertical > ul > li {
		flex-grow: 1;
	}

		.ipsTabs.ipsTabs_vertical > ul > li > a {
			width: 100%;
		}

.ipsTabs.ipsTabs_vertical .ipsTabs_item {
	border-top: 0;
	border-left: 2px solid transparent;
	margin-bottom: 2px;
	padding: 0 15px;
}

.ipsTabs.ipsTabs_vertical .ipsTabs_activeItem {
	border-left: 2px solid #3b6c99;
}

.cBulkRecipient_count {
	line-height: 24px;
	background: #ddd;
	color: #222;
	font-weight: 400;
	font-size: 12px;
	border-radius: 2px;
	display: inline-block;
	padding: 0 10px;
}
html[dir="ltr"] .cBulkRecipient_count {
	margin-left: 8px;
	margin-right: 8px;
}
html[dir="rtl"] .cBulkRecipient_count {
	margin-right: 8px;
	margin-left: 8px;
}

.ipsTabs_activeItem .cBulkRecipient_count {
	background: #3b6c99;
	color: #fff;
}

.ipsTreeList, .ipsTreeList ul {
	margin: 0;
	padding: 0;
	list-style: none;
}

	.ipsTreeList a {
		color: inherit;
		padding: 7px 0;
		font-size: 14px;
		display: block;
		position: relative;
	}

	html[dir="ltr"] .ipsTreeList li a { padding-left: 15px;	}
	html[dir="ltr"] .ipsTreeList li li a { padding-left: 30px; }
	html[dir="ltr"] .ipsTreeList li li li a { padding-left: 45px; }
	html[dir="ltr"] .ipsTreeList li li li li a { padding-left: 60px; }
	html[dir="rtl"] .ipsTreeList li a { padding-right: 15px; }
	html[dir="rtl"] .ipsTreeList li li a { padding-right: 30px; }
	html[dir="rtl"] .ipsTreeList li li li a { padding-right: 45px; }
	html[dir="rtl"] .ipsTreeList li li li li a { padding-right: 60px; }

	.ipsTreeList_inactiveBranch > ul {
		display: none;
	}

	.ipsTreeList_inactiveBranch > a:before,
	.ipsTreeList_activeBranch > a:before {
		font-family: 'FontAwesome';
		font-size: 14px;
		line-height: 6px;
	}

		html[dir="ltr"] .ipsTreeList_inactiveBranch > a:before,
		html[dir="ltr"] .ipsTreeList_activeBranch > a:before {
			margin-right: 7px;
		}
		html[dir="rtl"] .ipsTreeList_inactiveBranch > a:before,
		html[dir="rtl"] .ipsTreeList_activeBranch > a:before {
			margin-right: 7px;
		}

		.ipsTreeList_inactiveBranch > a:before {
			content: '\f0da';
		}
		.ipsTreeList_activeBranch > a:before {
			content: '\f0d7';
		}

	.ipsTreeList_activeNode > a {
		background: #3B6C99;
		background: var(--primary);
		color: #fff;
	}

.ipsTree, .ipsTree ol {
	list-style: none;
	margin: 0;
	padding: 0;
}

.ipsTree {
	margin: 7px;
}

.ipsTree_row {
	display: flex;
	align-items: center;
	padding: 15px;
}

	.ipsTree_row > *{
		min-width: 0;
	}

	.ipsTree_row + form > .ipsTree_rows {
		padding-left: 15px;
	}

.ipsTree_row:hover .ipsControlStrip {
	opacity: 1;
}

html[dir="ltr"] .ipsTree_loadingRow {
	padding: 10px 10px 10px 30px;
}
	html[dir="ltr"] .ipsTree_loadingRow:before {
		left: 15px;
	}
html[dir="rtl"] .ipsTree_loadingRow {
	padding: 10px 30px 10px 10px;
}
	html[dir="rtl"] .ipsTree_loadingRow:before {
		right: 15px;
	}

/* Cell types */
.ipsTree_drag {
	min-width: 30px;
	text-align: center;
}

	.ipsTree_drag .ipsTree_dragHandle {
		opacity: 0.2;
		cursor: move;
	}

.ipsTree_controls {
	flex: 0 0 110px;
	align-self: flex-start;
}

	.ipsTree_controls .ipsControlStrip {
		float: right;
	}
	html[dir="rtl"] .ipsTree_controls .ipsControlStrip {
		float: left;
	}

.ipsTree_rowData {
	padding: 0 10px;
	flex: 1 1 auto;
	position: relative;
}

.ipsTree_badge {
	padding-right: 10px;
	vertical-align: middle;
}

.ipsTree_icon {
	width: 24px;
}

/* Stack styles */
.ipsTree_rowData h4 {
	margin: 0;
	width: 100%;
	font-weight: normal;
	font-size: 14px;
}

.ipsTree_parent.ipsTree_row:not( .ipsTree_noToggle ):hover {
	/* background: rgba(245,246,247,0.7); */
	cursor: pointer;
}

html[dir="ltr"] .ipsTree_parent.ipsTree_row > .ipsTree_rowData {
	padding-left: 35px;
}
html[dir="rtl"] .ipsTree_parent.ipsTree_row > .ipsTree_rowData {
	padding-right: 35px;
}

	.ipsTree_parent.ipsTree_row > .ipsTree_rowData h4 {
		font-weight: 500;
		font-size: 16px;
		position: relative;
		display: inline-block;
	}

		.ipsJS_has .ipsTree_parent.ipsTree_row > .ipsTree_rowData h4 a {
			color: inherit;
		}

	.ipsTree_parent.ipsTree_row > .ipsTree_rowData h4:before {
		position: absolute;
		top: 5px;
		content: '\f04b';
		font-family: 'FontAwesome';
		font-size: 11px;
		text-align: center;
		display: block;
		opacity: 0.5;
		transition: 0.2s all linear;
	}
	html[dir="ltr"] .ipsTree_parent.ipsTree_row > .ipsTree_rowData h4:before {
		left: -25px;
	}
	html[dir="rtl"] .ipsTree_parent.ipsTree_row > .ipsTree_rowData h4:before {
		right: -25px;
	}

		.ipsTree_parent.ipsTree_row > .ipsTree_rowData h4:before {
			transform: rotate(0deg);
		}
		html[dir="rtl"] .ipsTree_parent.ipsTree_row > .ipsTree_rowData h4:before {
			transform: rotate(180deg);
		}

		.ipsTree_parent.ipsTree_open.ipsTree_row > .ipsTree_rowData h4:before {
			transform: rotate(90deg);
			opacity: 1;
		}
		html[dir="rtl"] .ipsTree_parent.ipsTree_open.ipsTree_row > .ipsTree_rowData h4:before {
			transform: rotate(90deg);
			opacity: 1;
		}

.ipsTree_row {
	border-bottom: 1px solid #f0f0f0;
	border-bottom-color: var(--c2);
}

.ipsTree_row.ipsTree_parent {
	border-bottom: 1px solid #f0f0f0;
	border-bottom-color: var(--c2);
}

	ol.ipsTree > li:last-child > .ipsTree_row:not( .ipsTree_open ) {
		border-bottom: 0;
	}

	.ipsTree_row.ipsTree_draggingInto {
		background: #cfcfcf;
	}

.ipsTree_row + ol .ipsTree_row {
	background: #fafafa;
	border-bottom: 1px solid #ececec;
}

.ipsTree_row + ol .ipsTree_row + ol .ipsTree_row {
	background: #fff;
	border-bottom: 1px solid #f4f4f4;
}

html[dir="ltr"] ol ol {
	margin-left: 28px;
}
html[dir="rtl"] ol ol {
	margin-right: 15px;
}

/* Open trees */
.ipsTree_row.ipsTree_open {

}

/* Nested sortable classes */
.mjs-nestedSortable-error {
	border: 1px solid #e85959 !important;
	background: #f3d9d9 !important;
	min-height: 48px !important;
	position: relative;
}

	.mjs-nestedSortable-error:before,
	.mjs-nestedSortable-error:after {
		display: block;
		position: absolute;
		line-height: 48px;
		font-size: 11px;
		color: #e85959;
	}

	.mjs-nestedSortable-error:before {
		content: attr(data-error);
		left: 30px;
	}

	.mjs-nestedSortable-error:after {
		content: '\f071';
		font-family: 'FontAwesome';
		left: 10px;
	}

.sortable-placeholder {
	border: 1px solid #59aee8;
	background: #d9e8f3;
	min-height: 48px;
}

.ipsTree_row .ipsTree_row_cells {

}

	.ipsTree_row .ipsTree_row_cells .ipsTree_row_cell {
		width: auto;
		border-right: 1px solid #f0f0f0;
		padding-right: 8px;
		padding-left: 8px;
		min-width: 75px;
		display: inline-block;
	}

		.ipsTree_row .ipsTree_row_cells .ipsTree_row_cell:last-child {
			border-right: 0px;
		}

.ipsType_richText{
	color: inherit;
}

.ipsType_veryLarge{
	color: var(--c8);
}

.ipsType_light {
	color: #587898;
