.ipsComment_toolWrap,
.ipsComment_tools {
	display: flex;
	align-items: center;
}
	.ipsApp .ipsComment_toolWrap{
		flex: 0 0 auto;
	}
	html[dir="ltr"] .ipsComment_tools {
