		font-size: 11px;
	}

	.ipsRating.ipsRating_large {
		font-size: 16px;
	}

	.ipsRating.ipsRating_veryLarge {
		font-size: 20px;
	}

	.ipsRating + span {
		margin-left: 10px;
	}

	.ipsRating + span:empty {
		margin-left: 0;
	}

/* Hover stuff for own ratings */
