/* SIMPLIFIED WRAPPER */
.ipsLayout_minimal #ipsLayout_header #elUserNav,
.ipsLayout_minimal #elSearch,
.ipsLayout_minimal #elMobileNav,
.ipsLayout_minimal .ipsBreadcrumb {
	display: none !important;
}

