}

.ipsScrollbar::-webkit-scrollbar-thumb { 
	background-color: rgba(0,0,0,0.4);
	border-radius: 3px;
}
	.ipsScrollbar.ipsScrollbar_light::-webkit-scrollbar-thumb { 
