	}

	.ipsCalendarDate_month {
		color: #a93848;
		text-transform: uppercase;
		font-size: {fontsize="10"};
		line-height: 1;
		font-weight: bold;
	}

	.ipsCalendarDate_date {
		font-size: {fontsize="x_large"};
		line-height: 1;
	}

	.ipsCalendarDate.ipsCalendarDate_large {
