		/* background: rgb( var(--theme-area_background_reset) ); */
		z-index: 4000;
	}

	.ipsSideMenu.ipsSideMenu_open .ipsSideMenu_list,
	.ipsSideMenu:target .ipsSideMenu_list {
		margin-bottom: 0;
	}
}

