/* ACHIEVEMENTS */
.cProfileAchievements {
	display: grid;
	grid-template-columns: repeat( auto-fit, minmax(170px, 1fr) );
	grid-column-gap: var(--sp-2);
	grid-row-gap: var(--sp-7);
}

	.cProfileAchievements > a:hover {
		background: rgb( var(--theme-area_background ) );
	}

.cProfileBadgeGrid {
	display: grid;
	grid-template-columns: repeat( auto-fit, minmax(250px, 1fr));
	grid-gap: var(--sp-5);
}

.cRankHistory {
	--line-width: 3px;
	z-index: 10;
}

	.cRankHistory:before {
		content: '';
		width: var(--line-width);
		background: rgb(var(--theme-text_light));
		position: absolute;
		top: -20px;
		bottom: calc( var(--size-4) / 2); /* Make the line end under the last image */
		left: calc( var(--size-4) / 2 - ( var(--line-width) / 2 ) );
		z-index: -1;
		opacity: 0.4;
	}

	.cRankHistory:after {
		content: '';
		background: rgb(var(--theme-text_light));
		width: calc(var(--line-width) * 3);
		height: calc(var(--line-width) * 3);
		position: absolute;
		top: calc( -20px - var(--line-width) );
		left: calc( var(--size-4) / 2 - (var(--line-width) / 2) - var(--line-width) );
		border-radius: calc( var(--line-width) * 3);
	}

	.cRankHistory__item {
		position: relative;
	}

		.cRankHistory__item:before {
			content: '';
			width: var(--size-4);
			height: calc( var(--size-4) + 6px );
			background: rgb(var(--theme-area_background_reset));
			position: absolute;
			left: 0;
			top: -3px;
		}

	.cRankHistory__itemBadge--unearned {
		opacity: 0.15;
		filter: grayscale(1);
	}

