/* CLASS LIST */
#vseClassWrap {
	width: var(--vse-width);
	overflow: hidden;
	position: absolute;
	top: 60px;
	bottom: 0;
	border-top: 1px solid rgba(0,0,0,0.6);
}
html[dir="ltr"] #vseClassWrap {
	left: 0;
}
html[dir="rtl"] #vseClassWrap {
	right: 0;
}

	#vseClassList, #vseClassEditor {
		width: var(--vse-width);
		position: absolute;
		top: 0;
		bottom: 0;
		transition: all 0.3s ease;
		overflow: auto;
	}

	html[dir="ltr"] #vseClassWrap #vseClassEditor {
		left: var(--vse-width);
	}
	html[dir="ltr"] #vseClassWrap.vseShow_editor #vseClassList {
		left: calc( var(--vse-width) * -1 );
	}
	html[dir="ltr"] #vseClassWrap #vseClassList {
		left: 0;
	}
	html[dir="ltr"] #vseClassWrap.vseShow_editor #vseClassEditor {
		left: 0;
	}
	html[dir="rtl"] #vseClassWrap #vseClassEditor {
		right: var(--vse-width);
	}
	html[dir="rtl"] #vseClassWrap.vseShow_editor #vseClassList {
		right: calc( var(--vse-width) * -1 );
	}
	html[dir="rtl"] #vseClassWrap #vseClassList {
		right: 0;
	}
	html[dir="rtl"] #vseClassWrap.vseShow_editor #vseClassEditor {
		right: 0;
	}

#vseClassList {
	color: #fff;
}

#vseClassList .vseClass_title {
	background: rgba(0,0,0,0.2);
	color: #fff;
	padding: 10px 15px;
	font-size: 15px;
	font-weight: 500;
	color: #949494;
}

#vseClassList li[data-styleID] {
	display: block;
	color: #fff;
	padding: 15px 0 15px 15px;
	position: relative;
	text-decoration: none;
	/*border-top: 1px solid rgba(0,0,0,0.2);*/
}
html[dir="rtl"] #vseClassList li[data-styleID] {
	padding: 15px 15px 15px 0;
}

	/*#vseClassList li[data-styleID] a:hover {
		background: rgba(255,255,255,0.05);
	}*/

	#vseClassList li[data-styleID] .vseClass_swatch {
		position: absolute;
		top: 5px;
	}
	html[dir="ltr"] #vseClassList li[data-styleID] .vseClass_swatch--back {
		right: 5px;
	}
	html[dir="rtl"] #vseClassList li[data-styleID] .vseClass_swatch--back {
		left: 5px;
	}

	html[dir="ltr"] #vseClassList li[data-styleID] .vseClass_swatch--fore {
		right: 50px;
	}
	html[dir="rtl"] #vseClassList li[data-styleID] .vseClass_swatch--fore {
		left: 50px;
	}


.vseClass_swatch {
	display: inline-block;
	width: 39px;
	height: 39px;
	text-align: center;
	line-height: 39px;
	border-radius: 4px;
	border: 1px solid rgba(255,255,255,0.3) !important;
}

	.vseClass_swatch--noStyle {
		font-size: 18px;
		font-weight: 300;
		color: rgba(255,255,255,0.1);
		border: 0 !important;
	}

.vseClass_swatch .sp-dd,
.vseColorizer_swatch .sp-dd {
	display: none !important;
}

.vseColorizer_swatch {
	border-radius: 4px;
	border: 1px solid rgba(255,255,255,0.3) !important;
}

/* PANELS */
#vseSettingsWrap {
	position: absolute;
	top: 0;
	bottom: 0;
	left: 0;
	right: 0;
	overflow: hidden;
