		font-weight: 300;
		color: #fff;
		letter-spacing: 0.3px;
	}

	.cDashboard_bulletin hr.ipsHr {
		border-color: rgba(255,255,255,0.1);
	}

	.cDashboard_bulletin i.fa-info-circle,
	.cDashboard_bulletin i.fa-warning {
		font-size: 54px;
		line-height: 1;
		color: rgba(255,255,255,0.4);
		text-shadow: none;
	}

/* COMMERCE */
.acpWidget_item #elNexusActions > li > a:hover {
	background: var(--c1);
}

	.acpWidget_item .cNexusActionBadge_off{
		background: var(--c4);
	}

table.diff {
	width: 100%;
}

table.diff td, table.diff th {
	width: 50%;
	max-width: 500px;
	overflow-x: auto;
}

table.diff td {
	padding: 10px;
	vertical-align: top;
	white-space: pre;
	white-space: pre-wrap;
	font-family: monospace;
}

.diffBlank {
	content: '&nbsp;';
}

.diffDeleted {
	background:rgb(255,224,224);
}

.diffInserted {
	background:rgb(224,255,224);
}

.acpEnhancement {
	padding-bottom: 65px;
	position: relative;
	border-top: 10px solid #d6dee7;
	border-top-color: var(--c4);
}

.acpEnhancement_enabled {
	border-top-color: #599451;
}

.acpEnhancement_enabled > .ipsBadge {
	position: absolute;
	top: -18px;
}
html[dir="ltr"] .acpEnhancement_enabled > .ipsBadge {
	right: -5px;
}
html[dir="rtl"] .acpEnhancement_enabled > .ipsBadge {
	left: -5px;
}

.acpEnhancement__title{
	display: flex;
	justify-content: space-between;
	align-items: center;
	padding: 15px 15px 0 15px;
}

	.acpEnhancement__title h3{
		font-size: 15px;
		font-weight: 600;
	}

.acpEnhancement_buttons {
	position: absolute;
	bottom: 15px;
	left: 15px;
	right: 15px;
}

	.acpEnhancement_buttons > li {
		margin-bottom: 0 !important;
	}

.acpEnhancement_logo {
	max-width: 100px;
	max-height: 50px;
}

body#elLogin {
	display: flex;
	justify-content: center;
	align-items: center;
	overflow: auto;
	padding-top: 0;
	margin: 0 auto;
}

#elLogin_box {
	width: 98%;
	max-width: 450px;
	padding: 30px;
}

.cAcpLoginBox {
	padding-left: 0;
	padding-right: 0;
}

	.cAcpLoginBox .ipsForm {
		margin: 0;
	}
	.cAcpLoginBox .ipsForm .ipsFieldRow:not( :last-child ) {
		margin-bottom: 15px;
	}

	#elLogin_box .ipsFieldRow{
		border-width: 0;
	}

	.cAcpLoginBox .ipsTabs_panel {
		background: transparent;
	}

.cAcpLoginBox_logo {
	text-align: center;
	margin: 30px 0;
}

.cAcpLoginBox_logo img{
	width: 80%;
	margin: 0 auto;
	display: block;
}

	.ipsDarkMode .cAcpLoginBox_logo img{
		filter: brightness(100);
	}

.cAcpLoginBox_button {
	margin-bottom: 5px;
}

/* Remove yellow auto-fill styles */
.cAcpLoginBox input{
	filter: none;
}


/* To make 2FA show as part of the form rather than a modal */
#elTwoFactorAuthentication.ipsModal {
	background: #f9f9f9;
	position: inherit;
}
#elTwoFactorAuthentication {
	position: inherit;
}
#elTwoFactorAuthentication > div {
	background: #f9f9f9;
	box-shadow: none;
	border-radius: none;
}

/*.cMenuManager {
	padding-bottom: 100px;
}*/

.cMenuManager .cMenuManager_column {
	width: 460px;
}

.cMenuManager .cMenuManager_column.cMenuManager_readyToSlide {
	overflow: hidden;
}

/* Columns */
.cMenuManager_editorWrapper {
	width: 200%;
}

.cMenuManager {

}

.cMenuManager > .ipsColumns > .ipsColumn {
	padding: 0;
}

.cMenuManager_main,
.cMenuManager_dropdown {
	width: 50%;
	float: left;
	position: relative;
	padding: 30px;
}
html[dir="rtl"] .cMenuManager_main,
html[dir="rtl"] .cMenuManager_dropdown {
	float: right;
}

html[dir='ltr'] .cMenuManager_main{
	padding-left: 0;
}
html[dir='rtl'] .cMenuManager_main{
	padding-right: 0;
}

.cMenuManager_main,
.cMenuManager_dropdown {

}

.cMenuManager_root {
	margin-top: 10px;
}

	.cMenuManager_root ol {
		list-style: none;
		margin: 0;
		padding: 0;
	}

	html[dir="ltr"] .cMenuManager_root ol {
		border-left: 1px solid #9e9e9e;
		border-left-color: var(--c3);
		padding-left: 15px;
		margin-left: 15px;
	}
	html[dir="rtl"] .cMenuManager_root ol {
		border-right: 1px solid #9e9e9e;
		border-right-color: var(--c3);
		padding-right: 15px;
		margin-right: 15px;
	}

		html[dir="ltr"] .cMenuManager_root ol ol {
			margin-left: 15px;
		}
		html[dir="rtl"] .cMenuManager_root ol ol {
			margin-right: 15px;
		}

		html[dir="ltr"] .cMenuManager_root ol:empty {
			border-left: 0;
		}
		html[dir="rtl"] .cMenuManager_root ol:empty {
			border-right: 0;
		}

	.cMenuManager_leaf {
		background: #fff;
		background: var(--c1);
		padding: 12px 10px;
		margin: 5px 0 5px -30px;
		border: 1px solid rgba(0,0,0,0.1);
		background-clip: padding-box;
		border-radius: 5px;
		box-shadow: 0px 2px 3px rgba(0,0,0,0.04);
		cursor: move;
	}

		.ipsDarkMode .cMenuManager_leaf{
			border-color: rgba(255,255,255,0.1) transparent transparent transparent;
			background-clip: border-box;
		}

	html[dir="rtl"] .cMenuManager_leaf {
		margin: 5px -30px 5px 0;
	}

		.cMenuManager_leaf.cMenuManager_active {
			background: #2E3D49;
			background: var(--menu-manager--active);
			color: #fff;
		}
		html[dir="ltr"] .cMenuManager_leaf.cMenuManager_active {
			border-width: 1px 0 1px 1px;
			margin-right: -30px;
			padding-right: 20px;
			border-top-right-radius: 0px;
			border-bottom-right-radius: 0px;
		}
		html[dir="rtl"] .cMenuManager_leaf.cMenuManager_active {
			border-width: 1px 1px 1px 0;
			margin-left: -30px;
			padding-left: 20px;
			border-top-left-radius: 0px;
			border-bottom-left-radius: 0px;
		}

		.cMenuManager_leaf .cMenuManager_leafTitle {
			font-size: 16px;
			font-weight: 500;
			margin: 0;
		}

			.cMenuManager_leaf + ol .cMenuManager_leaf {
				padding: 7px 10px;
			}

				html[dir="ltr"] .cMenuManager_leaf + ol .cMenuManager_leaf.cMenuManager_active {
					padding-right: 20px;
				}
				html[dir="rtl"] .cMenuManager_leaf + ol .cMenuManager_leaf.cMenuManager_active {
					padding-left: 20px;
				}

				.cMenuManager_leaf + ol .cMenuManager_leaf .cMenuManager_leafTitle {
					font-size: 14px;
				}

		.cMenuManager_leaf .cMenuManager_leafMeta {
			font-size: 12px;
		}

		.cMenuManager_leaf [data-action="removeItem"],
		.cMenuManager_dropdown .ipsMenu_item [data-action="removeItem"] {
			opacity: 0.1;
			transition: opacity 0.1s linear;
		}

			.cMenuManager_leaf:hover [data-action="removeItem"],
			.cMenuManager_dropdown .ipsMenu_item:hover [data-action="removeItem"] {
				opacity: 1;
			}

.cMenuManager_emptyHover {
	background: #ebf4f9;
	border: 1px solid #b1cbd9;
	background: var(--c3);
	border-color: var(--c6);
	border-radius: 4px;
	height: 37px;
	position: relative;
}
html[dir="ltr"] .cMenuManager_emptyHover {
	margin-left: -30px;
}
html[dir="rtl"] .cMenuManager_emptyHover {
	margin-right: -30px;
}

	.cMenuManager_emptyHover.cMenuManager_emptyError {
		background: #f9ebeb;
		color: #906161;
		border: 1px solid currentColor;
	}

	.ipsDarkMode .cMenuManager_emptyHover.cMenuManager_emptyError {
		background: #5f3434;
	}

		.cMenuManager_emptyHover.cMenuManager_emptyError:before {
			content: '\f00d';
			font-family: 'FontAwesome';
			font-size: 18px;
			position: absolute;
			line-height: 40px;
		}
		html[dir="ltr"] .cMenuManager_emptyHover.cMenuManager_emptyError:before {
			left: 10px;
		}
		html[dir="rtl"] .cMenuManager_emptyHover.cMenuManager_emptyError:before {
			right: 10px;
		}

/* Dropdown editor */
.cMenuManager_dropdown .ipsMenu {
	position: relative;
	top: 0;
	width: 80%;
	margin: 30px auto 50px auto;
	min-height: 30px;
	box-shadow: 0px 12px 60px rgba(0,0,0,0.2);
}
html[dir="ltr"] .cMenuManager_dropdown .ipsMenu {
	left: 0;
}
html[dir="rtl"] .cMenuManager_dropdown .ipsMenu {
	right: 0;
}

	.cMenuManager_dropdown .ipsMenu .ipsMenu_item > div {
		display: block;
		color: #333;
		color: var(--c8);
		padding: 8px 15px;
		cursor: move;
	}

	.cMenuManager_dropdown .ipsMenu .ipsMenu_item {
		border: 1px solid transparent;
	}

	.cMenuManager_dropdown .ipsMenu .ipsMenu_item a:hover {
		background: transparent;
	}

	.cMenuManager_dropdown .ipsMenu .ipsMenu_item.cMenuManager_active {
		background: #ebf4f9;
		border-color: #b1cbd9;
		background: var(--c3);
		border-color: var(--primary);
	}

.cMenuManager_dropdown .ipsButton_narrow {
	padding: 0;
	border: 0;
}

.cMenuManager_emptyList {
	line-height: 40px;
	font-size: 12px;
	font-style: italic;
	opacity: 0.8;
}

/* Form editor */
.cMenuManager_form {
	position: relative;
}

	.cMenuManager_form.cMenuManager_formActive {
		background: #2E3D49;
		background: var(--menu-manager--active);
		padding: 10px !important;
	}

		.cMenuManager_form.cMenuManager_formActive > div > div {
			border: 1px solid rgba(0,0,0,0.1);
		}
.cMenuManager_form > .cMenuManager_formLoading {
	position: absolute;
	top: 0;
	right: 0;
	bottom: 0;
	left: 0;
}

/* Preview panel */
.cMenuManager_preview {
	position: fixed;
	bottom: 0;
	background: #f5f5f5;
	height: 48px;
	z-index: 10000;
	font-size: 14px;
}
html[dir="ltr"] .cMenuManager_preview {
	right: 0;
	left: 320px;
}
html[dir="rtl"] .cMenuManager_preview {
	left: 0;
	right: 320px;
}

	.cMenuManager_preview h2 {
		background: #3480bb;
		background: var(--primary);
		color: #fff;
		line-height: 48px;
		padding: 0 15px;
		font-size: 16px;
		font-weight: 400;
	}

		.cMenuManager_preview h2 a,
		.cMenuManager_preview h2 a:hover {
			color: #fff;
		}

	.cMenuManager_preview #elPreviewTheme {
		opacity: 0.8;
	}

	.cMenuManager_preview [data-role="previewBody"] {
		position: absolute;
		left: 0;
		right: 0;
		top: 48px;
		bottom: 0;
	}

	.cMenuManager_preview iframe {
		position: absolute;
		top: 0;
		left: 0;
		right: 0;
		bottom: 0;
		width: 100%;
		border: 0;
		height: 300px;
	}

	.cMenuManager_preview [data-role='closePreview']:not( .ipsHide ) {
		display: block;
		background: #000;
		width: 40px;
		height: 40px;
		line-height: 40px;
		border-radius: 40px;
		margin-top: -10px;
		color: #fff;
		font-family: 'arial', sans-serif;
		text-align: center;
		font-size: 25px;
	}

/* Preview frame */
#elMenuManagerPreview_body {
	padding-top: 50px;
}

	#elMenuManagerPreview_body #ipsLayout_mainArea {
		min-height: 50px;
	}

.cNotification {
	position: relative;
}
	html[dir="ltr"] .cNotification {
		border-left-width: 10px;
	}
	html[dir="rtl"] .cNotification {
		border-right-width: 10px;
	}

.cNotification_dismiss {
	width: 28px;
	height: 28px;
	border-radius: 14px;
	background: #000;
	color: #fff;
	line-height: 28px;
	text-align: center;
	position: absolute;
	top: -5px;
}
	html[dir="ltr"] .cNotification_dismiss {
		right: -5px;
	}
	html[dir="rtl"] .cNotification_dismiss {
		left: -5px;
	}

.cNotification_dismiss:hover {
	color: #fff;
}

#elSkinHookEditor > .ipsColumns,
#elCodeHookEditor > .ipsColumns {
	min-height: 700px;
}

.cHookEditor_sidebar {
	background: white;
	background: var(--c0);
	height: 720px;
	overflow-y: scroll;
	overflow-x: hidden;
}

	.cHookEditor_sidebar li {
		cursor: pointer;
	}

html[dir="ltr"] .cHookEditor_content {
	margin-left: 7px;
}
html[dir="rtl"] .cHookEditor_content {
	margin-right: 7px;
}

	.cHookEditor_content .acpFormTabContent {
		border: 0;
		padding: 15px;
	}

	.cHookEditor_content .ipsTabs_item {
		max-width: 250px !important;
	}

.cHookEditor_content > .acpBlock {
	background: #fff;
	background: var(--c0);
}

#elHookEditor .CodeMirror {
	height: 700px;
}

.cHookEditor_tree {
	padding: 0 15px 15px 15px;
	line-height: 1.6;
	font-size: 11px;
	font-family: 'monaco', 'courier new', monospace;
}

.cHookEditor_tree > ul {
	padding: 0;
}

.cHookEditor_tree ul {
	list-style: none;
}

.cHookEditor_tree span {
	display: inline-block;
}

.cHookEditor_tree span[data-selectable]:hover {
	background: #f9f7d2;
	cursor: pointer;
}

	.ipsDarkMode .cHookEditor_tree span[data-selectable]:hover{
		background: var(--c3);
	}

.cHookEditor_tree span[data-unselectable] {
	opacity: 0.4;
}

.cHookEditor_sidebar .ipsSideMenu_item a, .cHookEditor_sidebar a.ipsSideMenu_item, .cHookEditor_sidebar span.ipsSideMenu_item{
	border-radius: 0;
}

/* Overview statistics */
@keyframes updated {
	0% { 
        background-color: var(--c4); 
    }
	100% { 
        background-color: var(--c1); 
    }
}

.cStatTile:not( .ipsHide ) {
    display: flex !important;
    flex-direction: column;
}

    .cStatTile--updated {
        animation: updated 2s 1 ease-out;
    }

    .cStatTile__title {
        color: #959595;
        color: var(--c5);
        font-size: 18px;
        font-weight: 500;
        text-align: center;
        padding: 20px 15px;
    }

    .cStatTile__subTitle {
        color: #959595;
        color: var(--c5);
        font-size: 13px;
        font-weight: 500;
        text-align: center;
        margin-bottom: 5px;
    }

    .cStatTile__header {
        position: relative;
    }

    .cStatTile__body {
        flex-grow: 1;
        padding: 0 15px 15px;
        display: flex;
        align-items: center;
        justify-content: center;
        min-height: 190px;
        position: relative;
    }

        .cStatTile__bodyInner {
            width: 100%;
        }

    .cStatTile__info {
        position: absolute;
        right: 15px;
        top: calc(50% - 13px);
        font-size: 17px;
        color: #7B7E83;
        color: var(--c4);
        border: 1px solid currentColor;
        opacity: 0.5;
        width: 26px;
        height: 26px;
        border-radius: 26px;
        display: flex;
        align-items: center;
        justify-content: center;
        cursor: help;
        transition: 0.2s all ease-in-out;
    }

        .cStatTile__info:hover {
            opacity: 1;
        }

        .cStatTile__form {
            cursor: pointer;
        }

        .cStatTile__info + .cStatTile__info {
            right: 45px;
        }

    .cStatTile__split {
        width: 50%;
        flex-grow: 1;
    }

.cStat__number {
    color: #252525;
    color: var(--c7);
    font-weight: bold;
    line-height: 1;
    display: block;
}
    .cStat__number--large {
        font-size: 50px;
        margin-bottom: 7px;
    }
    .cStat__number--medium {
        font-size: 40px;
        margin-bottom: 7px;
    }
    .cStat__number--small {
        font-size: 22px;
        margin-bottom: 5px;
        color: #676767;
        color: var(--c5);
    }

.cStat__change {
    font-weight: bold;
    line-height: 1;
    display: inline-block;
}
    .cStat__change--large {
        font-size: 17px;
    }
    .cStat__change--small {
        font-size: 12px;
    }


.cStatsGrid .ipsLoading {
	height: 100%;
}

	.cStatsGrid .ipsBox {
		position: relative;
		height: 100%;
	}
		.cStatsGrid .ipsBox > p {
			position: absolute;
			bottom: 0px;
		}

.cStatsFilters button[type="submit"] {
	margin-left: 30px;
}

.cStatsFilters #dateFilterInputs {
	display: inline-block;
	margin-right: 10px;
}

.ipsApp .cStatsFilters select,
.ipsApp .cStatsFilters .ipsField_short {
    padding: 7px 11px;
}

.ipsApp .cStatsFilters .ipsField_short {
    margin-left: 10px;
    margin-right: 10px;
}

.ipsApp .cStatsFilters .ipsField_short:last-child {
    margin-right: 0;
}

html[dir] .ipsHovercard .ipsForm_horizontal .ipsFieldRow > .ipsFieldRow_title {
    min-width: 200px;
    width: auto;
}

.ipsFieldRow_content {
    padding-left: 10px !important;
}
.ipsFieldRow_label {
    padding-left: 10px !important;
}
